window.LESSON={"slug":"cuddy","title":"Amy Cuddy · Your body language may shape who you are · TEDGlobal 2012","zhTitle":"肢体语言塑造你自己","audio":"../media/cuddy-ted.mp3","duration":1246,"segments":[{"n":1,"zh":"开场：检查你的姿势","en":"A free life hack","from":0,"to":8,"s":4.66,"e":50.69,"vocab":[{"w":"posture","ipa":"/ˈpɑːstʃər/","m":"n. 姿势；体态","ex":"Good posture is good for your back.","exzh":"良好的体态对背部有好处。"},{"w":"life hack","ipa":"/laɪf hæk/","m":"n. 生活小妙招","ex":"Here's a life hack for saving time.","exzh":"这是个省时间的生活小妙招。"},{"w":"audit","ipa":"/ˈɔːdɪt/","m":"n. 检查；审计","ex":"Do a quick audit of your spending.","exzh":"快速检查一下你的开支。"},{"w":"hunch","ipa":"/hʌntʃ/","m":"v. 弓背；耸肩","ex":"Don't hunch over your desk.","exzh":"别趴在桌上弓着背。"},{"w":"tweak","ipa":"/twiːk/","m":"v./n. 微调","ex":"Just tweak the plan a little.","exzh":"把计划稍微调整一下就好。"}],"gist":{"q":"她开场请大家做什么？","opts":["检查一下自己现在的身体姿势","闭上眼睛深呼吸","站起来鼓掌"],"ans":0,"sum":"她说有个免费妙招只需要两分钟改变姿势；先请大家看看自己此刻是否在弓背、跷腿、把自己缩小。"}},{"n":2,"zh":"我们如何解读肢体语言","en":"Judging nonverbals","from":9,"to":20,"s":50.69,"e":122.4,"vocab":[{"w":"body language","ipa":"/ˈbɑːdi ˌlæŋɡwɪdʒ/","m":"n. 肢体语言","ex":"His body language showed he was nervous.","exzh":"他的肢体语言显示他很紧张。"},{"w":"awkward","ipa":"/ˈɔːkwərd/","m":"adj. 尴尬的；笨拙的","ex":"There was an awkward silence.","exzh":"出现了一阵尴尬的沉默。"},{"w":"contemptuous","ipa":"/kənˈtemptʃuəs/","m":"adj. 轻蔑的","ex":"She gave him a contemptuous look.","exzh":"她轻蔑地看了他一眼。"},{"w":"handshake","ipa":"/ˈhændʃeɪk/","m":"n. 握手","ex":"He greeted me with a firm handshake.","exzh":"他和我有力地握了握手。"},{"w":"interaction","ipa":"/ˌɪntərˈækʃn/","m":"n. 互动","ex":"social interaction","exzh":"社交互动"}],"gist":{"q":"关于肢体语言，她指出我们常常忘了什么？","opts":["别人会评判我们","肢体语言也会影响我们自己","表情符号没用"],"ans":1,"sum":"人们会凭肢体语言做出重要判断（医生是否被起诉、选举结果），但我们忘了它也影响我们自己的想法、感受和生理。"}},{"n":3,"zh":"肢体语言能预测结果","en":"Judgments and outcomes","from":21,"to":33,"s":122.4,"e":209.77,"vocab":[{"w":"sweeping","ipa":"/ˈswiːpɪŋ/","m":"adj. 笼统的；全面的","ex":"Don't make sweeping judgments.","exzh":"别做笼统的判断。"},{"w":"inference","ipa":"/ˈɪnfərəns/","m":"n. 推断","ex":"What inference can we draw?","exzh":"我们能得出什么推断？"},{"w":"promote","ipa":"/prəˈmoʊt/","m":"v. 提拔；推广","ex":"She was promoted to manager.","exzh":"她被提拔为经理。"},{"w":"sue","ipa":"/suː/","m":"v. 起诉","ex":"He sued the company.","exzh":"他起诉了那家公司。"},{"w":"incompetent","ipa":"/ɪnˈkɑːmpɪtənt/","m":"adj. 不称职的","ex":"an incompetent driver","exzh":"一个不称职的司机"}],"gist":{"q":"人们根据肢体语言做出的判断能预测什么？","opts":["医生会不会被起诉、选举结果等","明天的天气","考试分数"],"ans":0,"sum":"仅看 30 秒无声医患片段就能预测医生是否被起诉；看候选人的脸一秒钟就能预测七成选举结果。但我们忘了，非语言信号也影响我们自己。"}},{"n":4,"zh":"权力的姿态：张开与蜷缩","en":"Power poses in nature","from":34,"to":64,"s":209.78,"e":316.94,"vocab":[{"w":"prejudice","ipa":"/ˈpredʒudɪs/","m":"n. 偏见","ex":"We should fight against prejudice.","exzh":"我们应该反对偏见。"},{"w":"inevitable","ipa":"/ɪnˈevɪtəbl/","m":"adj. 不可避免的","ex":"Change is inevitable.","exzh":"变化是不可避免的。"},{"w":"dominance","ipa":"/ˈdɑːmɪnəns/","m":"n. 支配地位；优势","ex":"The team showed total dominance.","exzh":"这支队伍展现了绝对优势。"},{"w":"take up space","ipa":"/teɪk ʌp speɪs/","m":"phr. 占据空间","ex":"The sofa takes up too much space.","exzh":"这张沙发太占地方了。"},{"w":"congenitally","ipa":"/kənˈdʒenɪtəli/","m":"adv. 先天地","ex":"He was congenitally blind.","exzh":"他先天失明。"}],"gist":{"q":"表达权力和支配的姿态有什么共同点？","opts":["把自己缩小","张开、伸展、占据空间","低头看地"],"ans":1,"sum":"动物和人类表达权力时都会张开身体，连先天失明的人赢得比赛也会举起双臂；感到无力时则收缩自己。"}},{"n":5,"zh":"MBA 课堂上的观察","en":"In the classroom","from":65,"to":86,"s":317.41,"e":424.94,"vocab":[{"w":"exhibit","ipa":"/ɪɡˈzɪbɪt/","m":"v. 表现出；展示","ex":"She exhibited great courage.","exzh":"她表现出了极大的勇气。"},{"w":"caricature","ipa":"/ˈkærɪkətʃər/","m":"n. 漫画式人物；夸张的模仿","ex":"He looked like a caricature of a rich man.","exzh":"他看起来像漫画里的有钱人。"},{"w":"occupy","ipa":"/ˈɑːkjupaɪ/","m":"v. 占据","ex":"The table occupies half the room.","exzh":"桌子占了半个房间。"},{"w":"participation","ipa":"/pɑːrˌtɪsɪˈpeɪʃn/","m":"n. 参与","ex":"Class participation counts for 20 percent.","exzh":"课堂参与占 20% 的分数。"},{"w":"fake it till you make it","ipa":"/feɪk ɪt tɪl ju meɪk ɪt/","m":"phr. 假装直到成功","ex":"Nervous? Fake it till you make it.","exzh":"紧张？先装出来，直到真的做到。"}],"gist":{"q":"她在 MBA 课堂上发现了什么？","opts":["姿势和性别、课堂参与有关","男生都不发言","所有人都很自信"],"ans":0,"sum":"有人一进教室就占据空间，有人缩成一团；这和性别有关，也和课堂参与有关，而参与占成绩一半。她想知道能否“假装直到成功”。"}},{"n":6,"zh":"身体能改变心灵吗？","en":"Can the body change the mind?","from":87,"to":98,"s":424.94,"e":493.48,"vocab":[{"w":"govern","ipa":"/ˈɡʌvərn/","m":"v. 支配；统治","ex":"Habits govern much of our life.","exzh":"习惯支配着我们生活的很大一部分。"},{"w":"hormone","ipa":"/ˈhɔːrmoʊn/","m":"n. 激素","ex":"Stress hormones rise when you are scared.","exzh":"害怕时压力激素会升高。"},{"w":"evidence","ipa":"/ˈevɪdəns/","m":"n. 证据","ex":"There is no evidence for that.","exzh":"这没有任何证据。"},{"w":"pretend","ipa":"/prɪˈtend/","m":"v. 假装","ex":"He pretended to be asleep.","exzh":"他假装睡着了。"},{"w":"physiological","ipa":"/ˌfɪziəˈlɑːdʒɪkl/","m":"adj. 生理的","ex":"physiological changes","exzh":"生理变化"}],"gist":{"q":"“有力量的领导者”通常有什么激素特点？","opts":["睾酮低、皮质醇高","睾酮高、皮质醇低","两种都高"],"ans":1,"sum":"非语言信号是双向的：心灵改变身体，身体也可能改变心灵；有力量又从容的领导者睾酮高、皮质醇低。"}},{"n":7,"zh":"权力者的激素","en":"Hormones of the powerful","from":99,"to":118,"s":493.69,"e":607.03,"vocab":[{"w":"testosterone","ipa":"/teˈstɑːstəroʊn/","m":"n. 睾酮（一种激素）","ex":"Testosterone is linked to dominance.","exzh":"睾酮与支配性有关。"},{"w":"cortisol","ipa":"/ˈkɔːrtɪsɑːl/","m":"n. 皮质醇（压力激素）","ex":"Stress raises cortisol levels.","exzh":"压力会让皮质醇升高。"},{"w":"abstractly","ipa":"/æbˈstræktli/","m":"adv. 抽象地","ex":"Try to think abstractly.","exzh":"试着抽象地思考。"},{"w":"hierarchy","ipa":"/ˈhaɪərɑːrki/","m":"n. 等级制度","ex":"the company hierarchy","exzh":"公司的等级制度"},{"w":"take risks","ipa":"/teɪk rɪsks/","m":"phr. 冒险","ex":"Successful people often take risks.","exzh":"成功的人常常敢于冒险。"}],"gist":{"q":"有力量又从容的领导者有什么激素特点？","opts":["睾酮高、皮质醇低","睾酮低、皮质醇高","两种都低"],"ans":0,"sum":"有权力的人更果断、自信、乐观、敢冒险；生理上睾酮高、皮质醇低。角色突然变化时，这些激素几天内就会改变。"}},{"n":8,"zh":"两分钟实验","en":"The two-minute experiment","from":119,"to":140,"s":607.03,"e":681.09,"vocab":[{"w":"experiment","ipa":"/ɪkˈsperɪmənt/","m":"n. 实验","ex":"We ran a simple experiment.","exzh":"我们做了一个简单的实验。"},{"w":"pose","ipa":"/poʊz/","m":"n. 姿势","ex":"Hold this pose for two minutes.","exzh":"保持这个姿势两分钟。"},{"w":"saliva","ipa":"/səˈlaɪvə/","m":"n. 唾液","ex":"The test uses a saliva sample.","exzh":"这项检测使用唾液样本。"},{"w":"prime","ipa":"/praɪm/","m":"v. 使有准备；启发","ex":"The ad primes you to buy.","exzh":"广告会引导你去购买。"},{"w":"vial","ipa":"/ˈvaɪəl/","m":"n. 小瓶","ex":"a vial of medicine","exzh":"一小瓶药"}],"gist":{"q":"做两分钟高权力姿势后，人们出现了什么变化？","opts":["睾酮上升、皮质醇下降，更愿意冒险","什么变化都没有","皮质醇上升"],"ans":0,"sum":"高权力组 86% 选择赌一把，睾酮升约 20%、皮质醇降约 25%；低权力组则相反。"}},{"n":9,"zh":"实验结果","en":"The results","from":141,"to":152,"s":681.16,"e":749.39,"vocab":[{"w":"risk tolerance","ipa":"/rɪsk ˈtɑːlərəns/","m":"n. 风险承受度","ex":"Young investors often have higher risk tolerance.","exzh":"年轻投资者的风险承受度通常更高。"},{"w":"significant","ipa":"/sɪɡˈnɪfɪkənt/","m":"adj. 显著的；重要的","ex":"a significant difference","exzh":"显著的差别"},{"w":"increase","ipa":"/ˈɪnkriːs/","m":"n. 增长","ex":"a 20 percent increase","exzh":"百分之二十的增长"},{"w":"decrease","ipa":"/ˈdiːkriːs/","m":"n. 下降","ex":"a sharp decrease in sales","exzh":"销量骤降"},{"w":"shut down","ipa":"/ʃʌt daʊn/","m":"phr. 关闭；（情绪上）封闭","ex":"She shut down when they criticized her.","exzh":"他们批评她时，她整个人都封闭了。"}],"gist":{"q":"两分钟高权力姿势带来了什么变化？","opts":["更愿意冒险，睾酮上升、皮质醇下降","没有变化","更害怕冒险"],"ans":0,"sum":"高权力组 86% 选择赌一把，睾酮升约 20%、皮质醇降约 25%；低权力组相反。身体改变了心灵。"}},{"n":10,"zh":"用在哪里？","en":"Where to use it","from":153,"to":176,"s":749.92,"e":833.32,"vocab":[{"w":"evaluative","ipa":"/ɪˈvæljueɪtɪv/","m":"adj. 评价性的","ex":"An exam is an evaluative situation.","exzh":"考试是一种被评价的场合。"},{"w":"threat","ipa":"/θret/","m":"n. 威胁","ex":"Speaking in public feels like a threat to many people.","exzh":"当众讲话对很多人来说像是一种威胁。"},{"w":"pitch","ipa":"/pɪtʃ/","m":"n. 推介；推销演说","ex":"She gave a great pitch to investors.","exzh":"她向投资人做了一次很棒的推介。"},{"w":"relate to","ipa":"/rɪˈleɪt tuː/","m":"phr. 能理解；产生共鸣","ex":"I can relate to your story.","exzh":"我能理解你的经历。"},{"w":"horrified","ipa":"/ˈhɔːrɪfaɪd/","m":"adj. 惊恐的；震惊的","ex":"We were horrified by the news.","exzh":"这条新闻让我们非常震惊。"}],"gist":{"q":"她建议在哪里使用权力姿势？","opts":["面试时当着面试官做","在面试前私下做两分钟","只在健身房做"],"ans":1,"sum":"它适合用在被评价的场合，但不是做给别人看，而是在进场前私下（比如在洗手间）做两分钟。"}},{"n":11,"zh":"面试实验：气场决定印象","en":"The job interview","from":177,"to":205,"s":833.32,"e":927.09,"vocab":[{"w":"job interview","ipa":"/dʒɑːb ˈɪntərvjuː/","m":"n. 求职面试","ex":"I have a job interview tomorrow.","exzh":"我明天有个求职面试。"},{"w":"feedback","ipa":"/ˈfiːdbæk/","m":"n. 反馈","ex":"Thanks for your feedback.","exzh":"谢谢你的反馈。"},{"w":"heckle","ipa":"/ˈhekl/","m":"v. 起哄；质问捣乱","ex":"The crowd heckled the speaker.","exzh":"人群对演讲者起哄。"},{"w":"spike","ipa":"/spaɪk/","m":"v. 急剧上升","ex":"Prices spiked last month.","exzh":"上个月价格飙升。"},{"w":"presence","ipa":"/ˈprezns/","m":"n. 风度；气场","ex":"She has a strong stage presence.","exzh":"她的舞台气场很强。"}],"gist":{"q":"面试实验中，评委更想雇用谁？为什么？","opts":["内容更好的人","做了高权力姿势、气场更自然的人","学历更高的人"],"ans":1,"sum":"评委不知道分组，却都想雇用高权力组；差别不在内容和资历，而在他们带出的状态——展现真实的自己。"}},{"n":12,"zh":"“感觉很假”：十九岁的车祸","en":"It feels fake","from":206,"to":218,"s":927.94,"e":986.29,"vocab":[{"w":"fraud","ipa":"/frɔːd/","m":"n. 骗子；欺诈","ex":"I felt like a fraud.","exzh":"我觉得自己像个骗子。"},{"w":"impostor","ipa":"/ɪmˈpɑːstər/","m":"n. 冒名顶替者","ex":"Many students feel like impostors.","exzh":"很多学生觉得自己是“冒牌货”。"},{"w":"resonate","ipa":"/ˈrezəneɪt/","m":"v. 引起共鸣","ex":"His words resonated with me.","exzh":"他的话让我很有共鸣。"},{"w":"rehab","ipa":"/ˈriːhæb/","m":"n. 康复治疗","ex":"He spent months in rehab.","exzh":"他做了好几个月康复治疗。"},{"w":"withdraw","ipa":"/wɪðˈdrɔː/","m":"v. 退出；使退学","ex":"She withdrew from the course.","exzh":"她退出了这门课程。"}],"gist":{"q":"她十九岁时发生了什么？","opts":["车祸后智商下降，被迫离开大学","考上了普林斯顿","开始教书"],"ans":0,"sum":"人们担心“假装”会让自己像骗子；这让她想起十九岁的车祸：她在脑外伤康复病房醒来，智商下降两个标准差，被迫休学。"}},{"n":13,"zh":"冒牌货的感觉","en":"Feeling like an impostor","from":219,"to":242,"s":986.42,"e":1078.83,"vocab":[{"w":"identity","ipa":"/aɪˈdentəti/","m":"n. 身份；认同","ex":"a sense of identity","exzh":"身份认同感"},{"w":"peer","ipa":"/pɪr/","m":"n. 同龄人；同辈","ex":"He finished earlier than his peers.","exzh":"他比同龄人更早完成。"},{"w":"advisor","ipa":"/ədˈvaɪzər/","m":"n. 导师；顾问","ex":"my PhD advisor","exzh":"我的博士导师"},{"w":"feel like a fraud","ipa":"/fiːl laɪk ə frɔːd/","m":"phr. 觉得自己像个骗子","ex":"I sometimes feel like a fraud at work.","exzh":"我有时在工作中觉得自己像个骗子。"},{"w":"outcome","ipa":"/ˈaʊtkʌm/","m":"n. 结果","ex":"a good outcome","exzh":"好的结果"}],"gist":{"q":"在普林斯顿第一次汇报前，导师对她说了什么？","opts":["你可以退出","不许退出，假装下去，直到你真的做到","换个专业吧"],"ans":1,"sum":"失去“聪明”的身份让她觉得完全无力；晚四年毕业后进入普林斯顿，仍觉得自己是冒牌货。导师苏珊·菲斯克让她每次都去讲，直到真正成为那样的人。"}},{"n":14,"zh":"她本该在这里","en":"She is supposed to be here","from":243,"to":263,"s":1079.94,"e":1166.31,"vocab":[{"w":"semester","ipa":"/sɪˈmestər/","m":"n. 学期","ex":"This semester I'm taking five classes.","exzh":"这学期我上五门课。"},{"w":"defeated","ipa":"/dɪˈfiːtɪd/","m":"adj. 挫败的；被打败的","ex":"He looked tired and defeated.","exzh":"他看起来又累又挫败。"},{"w":"internalize","ipa":"/ɪnˈtɜːrnəlaɪz/","m":"v. 内化","ex":"Practice until you internalize the rules.","exzh":"练到把规则内化为止。"},{"w":"fake it till you become it","ipa":"/feɪk ɪt tɪl ju bɪˈkʌm ɪt/","m":"phr. 假装直到成为","ex":"Don't just act confident — fake it till you become it.","exzh":"别只是装自信——装到真的变成那样的人。"},{"w":"turn around","ipa":"/tɜːrn əˈraʊnd/","m":"phr. 转过身","ex":"Everyone turned around to look at her.","exzh":"所有人都转过身看她。"}],"gist":{"q":"“假装直到成为”是什么意思？","opts":["一直假装，永远不变","坚持去做，直到真正变成那样的人","只在别人面前装"],"ans":1,"sum":"她在一个沉默的学生身上看到了从前的自己，鼓励她假装有力量；学生真的改变了。所以不只是装到成功，而是装到成为。"}},{"n":15,"zh":"两分钟，分享出去","en":"Share the science","from":264,"to":281,"s":1166.46,"e":1234.72,"vocab":[{"w":"cope","ipa":"/koʊp/","m":"v. 应对","ex":"How do you cope with stress?","exzh":"你怎么应对压力？"},{"w":"configure","ipa":"/kənˈfɪɡjər/","m":"v. 配置；调整","ex":"Configure the settings before you start.","exzh":"开始前先调整好设置。"},{"w":"ego","ipa":"/ˈiːɡoʊ/","m":"n. 自我；私心","ex":"Leave your ego at the door.","exzh":"把你的自我放在门外。"},{"w":"status","ipa":"/ˈsteɪtəs/","m":"n. 地位；身份","ex":"Money doesn't always bring status.","exzh":"钱不一定带来地位。"},{"w":"in private","ipa":"/ɪn ˈpraɪvət/","m":"phr. 私下里","ex":"Can we talk in private?","exzh":"我们能私下谈谈吗？"}],"gist":{"q":"她最后请大家做两件事，是什么？","opts":["试试权力姿势，并把这门科学分享出去","买她的书，关注她","每天锻炼两小时"],"ans":0,"sum":"微小的调整带来巨大改变：在紧张场合前花两分钟摆权力姿势；也请把它分享给最需要、却最缺少资源和权力的人。"}}],"sentences":[{"id":0,"p":0,"en":"So I want to start by offering you a free no-tech life hack, and all it requires of you is this: that you change your posture for two minutes.","zh":"我想先送给大家一个免费、不需要任何技术的生活小妙招，你只需要做一件事：花两分钟改变一下你的姿势。","s":4.66,"e":16.3,"w":[[4.78,4.86],[5.02,5.04],[5.06,5.18],[5.2,5.26],[5.32,5.6],[5.66,5.84],[6.3,6.68],[6.72,6.78],[6.84,6.86],[7.0,7.32],[7.97,8.11],[8.27,8.49],[8.57,8.81],[8.85,9.11],[10.59,10.71],[10.81,10.93],[10.99,11.05],[11.09,11.61],[11.65,11.73],[11.77,11.91],[12.05,12.15],[12.21,12.47],[12.55,12.67],[12.71,12.79],[12.87,13.23],[13.25,13.37],[13.39,14.03],[14.83,15.11],[15.37,15.59],[15.65,16.05]]},{"id":1,"p":0,"en":"But before I give it away, I want to ask you to right now do a little audit of your body and what you're doing with your body.","zh":"不过在揭晓之前，我想请大家现在就给自己的身体做个小检查，看看你的身体正在做什么。","s":16.47,"e":23.02,"w":[[16.59,16.73],[16.79,17.09],[17.17,17.19],[17.23,17.37],[17.39,17.45],[17.49,17.81],[18.25,18.27],[18.29,18.41],[18.43,18.47],[18.57,18.79],[18.85,18.93],[18.97,19.07],[19.19,19.43],[19.49,19.75],[20.07,20.15],[20.23,20.25],[20.31,20.51],[20.67,20.95],[21.07,21.17],[21.23,21.37],[21.45,21.75],[21.87,21.95],[21.97,22.09],[22.11,22.25],[22.27,22.48],[22.48,22.6],[22.62,22.72],[22.74,23.02]]},{"id":2,"p":0,"en":"So how many of you are sort of making yourselves smaller?","zh":"你们当中有多少人，正在让自己显得更小一点？","s":23.02,"e":25.8,"w":[[23.66,23.74],[23.84,23.96],[24.0,24.12],[24.2,24.26],[24.3,24.4],[24.44,24.54],[24.54,24.68],[24.68,24.72],[24.76,25.02],[25.02,25.38],[25.46,25.88]]},{"id":3,"p":0,"en":"Maybe you're hunching, crossing your legs, maybe wrapping your ankles.","zh":"也许你正弓着背、跷着腿，或者把脚踝缠在一起。","s":25.8,"e":29.78,"w":[[25.92,26.08],[26.1,26.24],[26.3,26.8],[27.68,28.06],[28.08,28.18],[28.26,28.62],[28.66,28.84],[28.9,29.24],[29.26,29.36],[29.46,29.84]]},{"id":4,"p":0,"en":"Sometimes we hold onto our arms like this.","zh":"有时我们会像这样抱住自己的胳膊。","s":29.78,"e":32.45,"w":[[29.9,30.3],[30.32,30.38],[30.46,30.64],[30.68,30.9],[30.98,31.08],[31.28,31.58],[31.66,31.84],[31.9,32.2]]},{"id":5,"p":0,"en":"Sometimes we spread out.","zh":"有时我们又会舒展开来。","s":33.74,"e":36.23,"w":[[33.86,34.46],[34.56,34.66],[35.32,35.62],[35.7,35.98]]},{"id":6,"p":0,"en":"I see you.","zh":"我看到你们了。","s":37.47,"e":38.26,"w":[[37.59,37.61],[37.69,37.87],[37.91,38.01]]},{"id":7,"p":0,"en":"So I want you to pay attention to what you're doing right now.","zh":"所以请留意你此刻正在做的动作。","s":39.39,"e":41.91,"w":[[39.51,39.59],[40.01,40.03],[40.05,40.17],[40.21,40.27],[40.29,40.33],[40.37,40.51],[40.53,40.87],[40.87,40.91],[40.91,40.99],[41.01,41.13],[41.13,41.33],[41.35,41.51],[41.53,41.71]]},{"id":8,"p":0,"en":"We're going to come back to that in a few minutes, and I'm hoping that if you learn to tweak this a little bit, it could significantly change the way your life unfolds.","zh":"几分钟后我们再回到这个话题，我希望如果你学会稍微调整一下，它能大大改变你人生的走向。","s":41.91,"e":50.69,"w":[[42.03,42.13],[42.13,42.23],[42.23,42.27],[42.31,42.45],[42.47,42.63],[42.67,42.73],[42.77,43.03],[43.43,43.51],[43.53,43.55],[43.59,43.75],[43.83,44.19],[44.51,44.61],[44.65,44.75],[44.79,45.05],[45.07,45.19],[45.31,45.39],[45.43,45.55],[45.93,46.09],[46.13,46.19],[46.25,46.49],[46.53,46.65],[46.71,46.73],[46.79,46.97],[47.03,47.25],[47.67,47.75],[47.81,48.01],[48.09,48.69],[48.77,49.23],[49.35,49.43],[49.47,49.57],[49.61,49.71],[49.75,49.99],[50.03,50.69]]},{"id":9,"p":1,"en":"So, we're really fascinated with body language, and we're particularly interested in other people's body language.","zh":"我们对肢体语言非常着迷，尤其对别人的肢体语言感兴趣。","s":50.69,"e":59.77,"w":[[52.32,52.42],[52.64,52.82],[52.86,53.06],[53.22,54.04],[54.16,54.3],[54.36,54.62],[54.72,55.22],[55.68,55.84],[55.98,56.14],[56.16,56.84],[56.96,57.52],[57.98,58.06],[58.16,58.36],[58.4,58.72],[58.76,59.0],[59.08,59.52]]},{"id":10,"p":1,"en":"You know, we're interested in, like, you know — — an awkward interaction, or a smile, or a contemptuous glance, or maybe a very awkward wink, or maybe even something like a handshake.","zh":"比如，我们会关注——一次尴尬的互动、一个微笑、一个轻蔑的眼神，或者一次很尴尬的眨眼，甚至像握手这样的事。","s":59.84,"e":75.26,"w":[[59.96,60.02],[60.02,60.12],[60.14,60.28],[60.3,60.72],[60.86,61.02],[61.42,61.6],[61.96,62.02],[62.02,62.18],[66.12,66.2],[66.32,66.64],[66.68,67.43],[67.57,67.65],[67.67,67.69],[67.81,68.39],[68.51,68.57],[68.59,68.61],[68.65,69.27],[69.33,69.87],[69.93,70.01],[70.05,70.33],[70.81,70.83],[70.89,71.07],[71.17,71.47],[71.55,71.87],[72.89,72.97],[73.01,73.25],[73.35,73.55],[73.63,73.93],[73.95,74.11],[74.13,74.15],[74.27,75.01]]},{"id":11,"p":2,"en":"Narrator: Here they are arriving at Number 10.","zh":"旁白：他们抵达唐宁街 10 号了。","s":76.49,"e":78.34,"w":[[76.61,76.73],[76.75,76.85],[76.89,77.01],[77.01,77.43],[77.43,77.47],[77.51,77.75],[77.83,78.09]]},{"id":12,"p":2,"en":"This lucky policeman gets to shake hands with the President of the United States.","zh":"这位幸运的警察得以和美国总统握手。","s":79.09,"e":83.27,"w":[[79.21,79.33],[79.37,79.57],[79.63,80.11],[80.19,80.37],[80.41,80.49],[80.57,80.85],[80.87,81.15],[81.17,81.27],[81.27,81.33],[81.39,81.87],[81.95,82.02],[82.04,82.12],[82.16,82.56],[82.64,83.02]]},{"id":13,"p":2,"en":"Here comes the Prime Minister -- No.","zh":"首相来了——没有握手。","s":83.54,"e":86.03,"w":[[83.66,83.76],[83.76,83.94],[83.96,84.02],[84.04,84.28],[84.3,84.62],[85.7,85.78]]},{"id":14,"p":4,"en":"So a handshake, or the lack of a handshake, can have us talking for weeks and weeks and weeks.","zh":"所以一次握手，或者没有握手，就能让我们议论好几个星期。","s":91.06,"e":97.63,"w":[[91.18,91.3],[92.1,92.12],[92.22,92.82],[92.92,92.98],[93.02,93.08],[93.14,93.36],[93.4,93.48],[93.5,93.52],[93.6,94.22],[94.72,94.9],[94.98,95.18],[95.2,95.32],[95.4,95.88],[96.42,96.56],[96.62,96.93],[96.97,97.05],[97.07,97.29],[97.31,97.39],[97.43,97.67]]},{"id":15,"p":4,"en":"Even the BBC and The New York Times.","zh":"连 BBC 和《纽约时报》都在报道。","s":97.63,"e":99.48,"w":[[97.75,97.91],[97.95,98.01],[98.03,98.35],[98.49,98.55],[98.55,98.61],[98.63,98.71],[98.73,98.87],[98.91,99.23]]},{"id":16,"p":4,"en":"So obviously when we think about nonverbal behavior, or body language -- but we call it nonverbals as social scientists -- it's language, so we think about communication.","zh":"显然，当我们想到非语言行为，或者说肢体语言——我们社会科学家叫它“非语言信号”——它是一种语言，所以我们会想到交流。","s":100.03,"e":109.39,"w":[[100.15,100.25],[100.59,101.15],[101.31,101.43],[101.47,101.55],[101.69,101.87],[101.93,102.21],[102.53,102.99],[103.03,103.41],[103.59,103.65],[103.69,103.93],[104.01,104.37],[104.39,104.51],[104.53,104.59],[104.65,104.81],[104.83,104.89],[104.95,105.57],[105.63,105.71],[105.77,106.03],[106.05,106.59],[107.05,107.15],[107.23,107.71],[107.77,107.83],[107.89,107.95],[108.01,108.19],[108.21,108.41],[108.45,109.17]]},{"id":17,"p":4,"en":"When we think about communication, we think about interactions.","zh":"想到交流，我们就会想到互动。","s":109.39,"e":112.34,"w":[[109.51,109.61],[109.65,109.69],[109.75,109.89],[109.91,110.07],[110.09,110.77],[110.81,110.89],[110.95,111.11],[111.13,111.33],[111.37,112.12]]},{"id":18,"p":4,"en":"So what is your body language communicating to me?","zh":"那么你的肢体语言在向我传达什么？","s":112.34,"e":114.95,"w":[[112.46,112.54],[112.62,112.76],[112.8,112.88],[112.94,113.1],[113.14,113.36],[113.44,113.78],[113.82,114.38],[114.44,114.5],[114.6,114.7]]},{"id":19,"p":4,"en":"What's mine communicating to you?","zh":"我的又在向你传达什么？","s":115.16,"e":116.95,"w":[[115.28,115.46],[115.52,115.76],[115.8,116.38],[116.42,116.48],[116.58,116.7]]},{"id":20,"p":5,"en":"And there's a lot of reason to believe that this is a valid way to look at this.","zh":"有很多理由让我们相信，这是一种看待问题的合理方式。","s":117.1,"e":122.4,"w":[[117.22,117.3],[117.32,117.5],[117.6,117.62],[117.74,117.96],[118.0,118.08],[118.36,118.76],[119.2,119.26],[120.02,120.18],[120.18,120.28],[120.8,120.92],[120.96,121.02],[121.06,121.08],[121.16,121.52],[121.72,121.84],[121.86,121.92],[121.98,122.12],[122.16,122.22],[122.26,122.4]]},{"id":21,"p":5,"en":"So social scientists have spent a lot of time looking at the effects of our body language, or other people's body language, on judgments.","zh":"社会科学家花了大量时间研究我们的肢体语言或者别人的肢体语言，对判断有什么影响。","s":122.4,"e":129.65,"w":[[122.52,122.58],[122.58,122.88],[122.88,123.26],[123.26,123.34],[123.36,123.54],[123.58,123.6],[123.66,123.8],[123.82,123.86],[123.9,124.3],[124.78,125.04],[125.06,125.12],[125.14,125.2],[125.24,125.6],[126.14,126.26],[126.48,126.68],[126.75,126.97],[127.07,127.39],[127.43,127.51],[127.57,127.75],[127.77,128.01],[128.05,128.25],[128.31,128.63],[128.71,128.81],[128.87,129.41]]},{"id":22,"p":5,"en":"And we make sweeping judgments and inferences from body language.","zh":"我们会根据肢体语言做出笼统的判断和推断。","s":129.65,"e":133.42,"w":[[129.77,129.87],[129.89,129.95],[130.03,130.27],[130.35,130.75],[130.79,131.19],[131.23,131.33],[131.79,132.29],[132.31,132.45],[132.49,132.71],[132.79,133.17]]},{"id":23,"p":5,"en":"And those judgments can predict really meaningful life outcomes like who we hire or promote, who we ask out on a date.","zh":"而这些判断能预测人生中非常重要的结果，比如我们雇用或提拔谁，约谁出去。","s":133.53,"e":141.07,"w":[[133.65,133.89],[133.97,134.17],[134.23,134.85],[135.27,135.43],[135.47,135.77],[135.91,136.19],[136.27,136.67],[136.71,136.95],[136.99,137.37],[137.39,137.55],[137.57,137.67],[137.77,137.83],[137.93,138.21],[138.27,138.33],[138.37,138.89],[139.49,139.59],[139.67,139.73],[139.85,140.03],[140.11,140.23],[140.27,140.35],[140.41,140.43],[140.49,140.83]]},{"id":24,"p":5,"en":"For example, Nalini Ambady, a researcher at Tufts University, shows that when people watch 30-second soundless clips of real physician-patient interactions,","zh":"比如，塔夫茨大学的研究者纳里尼·安巴迪发现，人们观看真实医患互动的 30 秒无声片段时，","s":141.07,"e":153.15,"w":[[141.19,141.29],[141.31,141.8],[143.58,143.9],[144.0,144.36],[144.42,144.44],[144.5,144.86],[144.88,144.92],[144.96,145.2],[145.3,145.76],[145.9,146.18],[146.22,146.36],[146.82,146.94],[147.0,147.3],[147.36,147.6],[147.8,148.98],[149.08,149.38],[149.54,149.98],[150.08,150.42],[150.52,150.6],[150.7,150.94],[151.06,151.54],[151.64,152.02],[152.1,152.9]]},{"id":25,"p":5,"en":"their judgments of the physician's niceness predict whether or not that physician will be sued.","zh":"他们对医生是否和善的判断，能预测这位医生会不会被起诉。","s":153.36,"e":158.64,"w":[[153.48,153.62],[153.7,154.16],[154.18,154.24],[154.28,154.36],[154.42,154.9],[155.04,155.7],[156.4,156.73],[156.77,156.97],[156.97,157.03],[157.05,157.17],[157.21,157.31],[157.35,157.71],[157.75,157.87],[157.89,157.95],[158.07,158.39]]},{"id":26,"p":5,"en":"So it doesn't have to do so much with whether or not that physician was incompetent, but do we like that person and how they interacted?","zh":"所以这和医生是否称职关系不大，而在于我们是否喜欢这个人，以及他们如何与人互动。","s":158.85,"e":164.66,"w":[[158.97,159.03],[159.07,159.11],[159.13,159.35],[159.37,159.47],[159.49,159.57],[159.63,159.73],[159.85,159.93],[160.03,160.21],[160.25,160.41],[160.49,160.71],[160.71,160.77],[160.79,160.93],[160.97,161.11],[161.17,161.49],[161.53,161.63],[161.65,162.23],[162.27,162.39],[162.43,162.49],[162.53,162.57],[162.65,162.87],[162.89,163.01],[163.05,163.35],[163.37,163.45],[163.49,163.61],[163.65,163.75],[163.81,164.41]]},{"id":27,"p":5,"en":"Even more dramatic, Alex Todorov at Princeton has shown us that judgments of political candidates' faces in just one second predict 70 percent of U.S. Senate and gubernatorial race outcomes, and","zh":"更惊人的是，普林斯顿的亚历克斯·托多罗夫发现，人们只看候选人的脸一秒钟做出的判断，就能预测 70% 的美国参议员和州长选举结果，","s":165.67,"e":180.8,"w":[[165.79,165.97],[166.01,166.19],[166.23,166.71],[167.15,167.35],[167.43,167.83],[167.87,167.93],[167.97,168.31],[168.35,168.45],[168.49,168.71],[168.75,168.87],[168.95,169.13],[169.89,170.35],[170.49,170.61],[170.93,171.31],[171.37,171.84],[171.96,172.52],[173.02,173.16],[173.34,173.56],[173.8,173.96],[174.1,174.58],[174.94,175.24],[175.32,175.64],[175.7,176.12],[176.22,176.3],[176.46,176.78],[176.92,177.3],[177.7,177.8],[177.82,178.46],[178.56,178.84],[178.96,179.62],[180.42,180.72]]},{"id":28,"p":5,"en":"even, let's go digital, emoticons used well in online negotiations can lead you to claim more value from that negotiation.","zh":"甚至在数字世界里，在网上谈判中用好表情符号，也能让你从谈判中争取到更多利益。","s":180.8,"e":189.46,"w":[[180.92,181.24],[181.58,181.76],[181.88,181.94],[182.1,182.52],[183.0,183.94],[184.56,184.78],[184.86,185.12],[185.24,185.32],[185.46,185.8],[185.82,186.55],[186.67,186.81],[186.95,187.15],[187.19,187.25],[187.29,187.37],[187.43,187.69],[187.75,187.91],[187.93,188.27],[188.29,188.39],[188.43,188.53],[188.55,189.21]]},{"id":29,"p":5,"en":"If you use them poorly, bad idea.","zh":"要是用得不好，那可就糟了。","s":189.53,"e":191.8,"w":[[189.65,189.71],[189.75,189.83],[189.89,190.03],[190.05,190.17],[190.21,190.57],[190.99,191.19],[191.31,191.55]]},{"id":30,"p":5,"en":"Right?","zh":"对吧？","s":191.91,"e":192.48,"w":[[192.03,192.23]]},{"id":31,"p":6,"en":"So when we think of nonverbals, we think of how we judge others, how they judge us and what the outcomes are.","zh":"所以想到非语言信号时，我们想的是自己如何评判别人、别人如何评判我们，以及会带来什么结果。","s":192.56,"e":198.61,"w":[[193.53,193.61],[193.91,194.01],[194.05,194.09],[194.15,194.31],[194.33,194.39],[194.43,194.95],[194.99,195.05],[195.09,195.23],[195.23,195.29],[195.33,195.47],[195.51,195.57],[195.63,195.89],[195.97,196.23],[196.31,196.43],[196.45,196.57],[196.61,196.87],[196.97,197.17],[197.31,197.39],[197.43,197.55],[197.57,197.65],[197.73,198.15],[198.21,198.37]]},{"id":32,"p":6,"en":"We tend to forget, though, the other audience that's influenced by our nonverbals, and that's ourselves.","zh":"但我们往往忘了，还有另一位观众也受我们非语言信号的影响，那就是我们自己。","s":198.61,"e":204.31,"w":[[198.73,198.81],[198.89,199.09],[199.11,199.17],[199.23,199.53],[199.59,199.79],[199.81,199.89],[200.03,200.25],[200.41,200.91],[200.97,201.15],[201.21,201.66],[201.66,201.76],[201.8,201.88],[201.9,202.48],[202.86,202.96],[203.0,203.22],[203.4,204.06]]},{"id":33,"p":6,"en":"We are also influenced by our nonverbals, our thoughts and our feelings and our physiology.","zh":"我们自己的想法、感受和生理状态，也会受到自身非语言信号的影响。","s":204.5,"e":209.77,"w":[[204.62,204.72],[204.94,205.08],[205.16,205.44],[205.58,206.14],[206.16,206.26],[206.32,206.4],[206.44,207.1],[207.38,207.46],[207.52,207.84],[207.9,208.0],[208.02,208.1],[208.16,208.52],[208.6,208.72],[208.74,208.82],[208.86,209.52]]},{"id":34,"p":7,"en":"So what nonverbals am I talking about?","zh":"那我说的是哪些非语言信号呢？","s":209.78,"e":212.43,"w":[[209.9,210.0],[210.72,210.86],[210.9,211.36],[211.4,211.48],[211.54,211.56],[211.62,211.94],[211.96,212.18]]},{"id":35,"p":7,"en":"I'm a social psychologist.","zh":"我是一名社会心理学家。","s":212.74,"e":214.33,"w":[[212.86,212.92],[212.96,212.98],[213.04,213.32],[213.34,214.08]]},{"id":36,"p":7,"en":"I study prejudice, and I teach at a competitive business school, so it was inevitable that I would become interested in power dynamics.","zh":"我研究偏见，在一所竞争激烈的商学院任教，所以我对权力关系产生兴趣是必然的。","s":214.7,"e":222.78,"w":[[214.82,214.84],[214.9,215.1],[215.18,215.78],[216.41,216.49],[216.57,216.59],[216.63,216.83],[216.85,216.91],[216.93,216.95],[216.99,217.45],[217.47,217.77],[217.83,218.11],[218.55,218.65],[219.49,219.55],[219.57,219.69],[219.75,220.27],[220.31,220.41],[220.49,220.51],[220.51,220.63],[220.65,220.99],[221.07,221.47],[221.49,221.55],[221.59,221.89],[221.95,222.53]]},{"id":37,"p":7,"en":"I became especially interested in nonverbal expressions of power and dominance.","zh":"我尤其对权力和支配地位的非语言表达感兴趣。","s":223.03,"e":228.48,"w":[[223.15,223.17],[223.21,223.49],[223.51,224.07],[224.13,224.63],[224.83,224.97],[225.45,225.97],[226.01,226.69],[227.01,227.09],[227.15,227.47],[227.51,227.61],[227.63,228.23]]},{"id":38,"p":8,"en":"And what are nonverbal expressions of power and dominance?","zh":"那么，权力和支配地位的非语言表达是什么样的？","s":228.95,"e":231.64,"w":[[229.07,229.19],[229.35,229.51],[229.65,229.79],[229.83,230.23],[230.29,230.75],[230.79,230.83],[230.87,231.14],[231.16,231.24],[231.28,231.74]]},{"id":39,"p":8,"en":"Well, this is what they are.","zh":"嗯，就是这样的。","s":231.64,"e":233.66,"w":[[231.76,231.92],[232.66,232.8],[232.84,232.92],[232.94,233.06],[233.1,233.2],[233.28,233.44]]},{"id":40,"p":8,"en":"So in the animal kingdom, they are about expanding.","zh":"在动物界，它们都和“扩张”有关。","s":233.66,"e":236.66,"w":[[233.78,233.86],[233.98,234.04],[234.06,234.14],[234.24,234.52],[234.56,234.92],[235.3,235.46],[235.52,235.62],[235.66,235.88],[235.92,236.68]]},{"id":41,"p":8,"en":"So you make yourself big, you stretch out, you take up space, you're basically opening up.","zh":"你让自己变大、伸展开、占据空间，基本上就是在打开自己。","s":236.66,"e":242.64,"w":[[236.78,236.86],[236.92,237.0],[237.06,237.24],[237.26,237.64],[237.78,238.06],[238.48,238.58],[238.66,239.1],[239.22,239.48],[239.86,239.92],[240.1,240.36],[240.4,240.48],[240.56,240.9],[240.9,241.06],[241.06,241.52],[241.9,242.34],[242.46,242.62]]},{"id":42,"p":8,"en":"It's about opening up.","zh":"关键在于打开。","s":242.64,"e":244.09,"w":[[242.76,242.88],[242.92,243.2],[243.3,243.64],[243.7,243.84]]},{"id":43,"p":8,"en":"And this is true across the animal kingdom.","zh":"整个动物界都是如此。","s":244.28,"e":246.91,"w":[[244.4,244.62],[245.12,245.26],[245.3,245.4],[245.46,245.72],[245.8,246.19],[246.23,246.31],[246.39,246.63],[246.67,246.99]]},{"id":44,"p":8,"en":"It's not just limited to primates.","zh":"不仅限于灵长类动物。","s":246.91,"e":249.08,"w":[[247.03,247.17],[247.23,247.41],[247.49,247.69],[247.77,248.07],[248.09,248.15],[248.19,248.83]]},{"id":45,"p":8,"en":"And humans do the same thing.","zh":"人类也一样。","s":249.87,"e":251.54,"w":[[249.99,250.11],[250.17,250.49],[250.51,250.57],[250.65,250.71],[250.77,251.01],[251.05,251.29]]},{"id":46,"p":8,"en":"So they do this both when they have power sort of chronically, and also when they're feeling powerful in the moment.","zh":"人们在长期拥有权力时会这样做，在某一刻感到自己很有力量时也会这样做。","s":252.33,"e":259.1,"w":[[252.45,252.55],[252.71,252.81],[252.87,252.95],[253.01,253.15],[253.21,253.41],[253.87,253.97],[254.01,254.11],[254.23,254.51],[254.57,254.87],[254.95,255.11],[255.13,255.17],[255.23,255.79],[256.49,256.61],[256.67,256.89],[256.95,257.07],[257.09,257.23],[257.29,257.65],[257.67,258.13],[258.19,258.25],[258.27,258.35],[258.39,258.85]]},{"id":47,"p":8,"en":"And this one is especially interesting because it really shows us how universal and old these expressions of power are.","zh":"这个例子特别有意思，因为它真正说明了这些权力表达有多普遍、多古老。","s":259.15,"e":266.63,"w":[[259.27,259.37],[259.39,259.51],[259.59,259.69],[259.71,259.79],[259.83,260.27],[260.31,260.65],[260.67,260.87],[260.89,260.96],[261.04,261.3],[261.44,261.76],[261.82,261.98],[262.48,262.64],[262.82,263.36],[263.46,263.56],[263.78,264.12],[264.56,264.78],[264.94,265.52],[265.54,265.6],[265.66,266.0],[266.14,266.38]]},{"id":48,"p":8,"en":"This expression, which is known as pride, Jessica Tracy has studied.","zh":"这种表情叫作“骄傲”，杰西卡·特蕾西研究过它。","s":266.74,"e":271.07,"w":[[266.86,267.02],[267.06,267.56],[267.62,267.76],[267.8,267.88],[267.9,268.1],[268.12,268.2],[268.28,268.8],[269.46,269.78],[269.84,270.2],[270.26,270.36],[270.42,270.82]]},{"id":49,"p":8,"en":"She shows that people who are born with sight and people who are congenitally blind do this when they win at a physical competition.","zh":"她发现，无论是天生能看见的人，还是先天失明的人，在体育比赛中获胜时都会这样做。","s":271.08,"e":279.4,"w":[[271.2,271.3],[271.42,271.74],[271.8,271.94],[272.4,272.64],[272.68,272.76],[272.82,272.94],[272.96,273.24],[273.46,273.64],[273.78,274.12],[274.26,274.36],[274.38,274.6],[274.64,274.74],[274.82,274.92],[274.96,275.46],[275.5,275.99],[276.53,276.63],[276.73,277.01],[277.37,277.49],[277.51,277.63],[277.71,277.89],[278.03,278.11],[278.13,278.15],[278.19,278.51],[278.53,279.15]]},{"id":50,"p":8,"en":"So when they cross the finish line and they've won, it doesn't matter if they've never seen anyone do it.","zh":"当他们冲过终点线赢得比赛时，就算从没见过别人这样做，也没关系。","s":279.41,"e":283.37,"w":[[279.53,279.61],[279.67,279.77],[279.81,279.91],[279.97,280.23],[280.27,280.33],[280.35,280.61],[280.65,280.85],[280.87,280.95],[280.95,281.15],[281.17,281.41],[281.61,281.65],[281.67,281.87],[281.89,282.09],[282.11,282.15],[282.17,282.33],[282.37,282.57],[282.65,282.81],[282.85,283.17],[283.19,283.27],[283.35,283.43]]},{"id":51,"p":8,"en":"They do this.","zh":"他们都会这样做。","s":283.37,"e":284.46,"w":[[283.49,283.61],[283.67,283.75],[283.91,284.21]]},{"id":52,"p":8,"en":"So the arms up in the V, the chin is slightly lifted.","zh":"双臂举成 V 字形，下巴微微抬起。","s":284.75,"e":288.12,"w":[[284.87,284.95],[285.01,285.09],[285.27,285.51],[285.53,285.63],[285.67,285.73],[285.77,285.83],[285.89,285.91],[286.61,286.69],[286.75,286.95],[286.99,287.05],[287.09,287.41],[287.49,287.87]]},{"id":53,"p":9,"en":"What do we do when we feel powerless?","zh":"那我们感到无力时会怎么做？","s":288.45,"e":289.85,"w":[[288.57,288.67],[288.67,288.71],[288.77,288.83],[288.89,288.97],[289.01,289.11],[289.15,289.21],[289.25,289.41],[289.43,289.93]]},{"id":54,"p":9,"en":"We do exactly the opposite.","zh":"恰恰相反。","s":289.85,"e":291.67,"w":[[289.97,290.03],[290.09,290.15],[290.23,290.67],[290.73,290.8],[290.9,291.42]]},{"id":55,"p":9,"en":"We close up.","zh":"我们会收起来。","s":291.84,"e":292.74,"w":[[291.96,292.04],[292.12,292.54],[292.64,292.76]]},{"id":56,"p":9,"en":"We wrap ourselves up.","zh":"我们把自己裹起来。","s":292.74,"e":294.45,"w":[[292.86,292.94],[293.04,293.34],[293.4,293.88],[294.02,294.2]]},{"id":57,"p":9,"en":"We make ourselves small.","zh":"我们让自己变小。","s":294.52,"e":295.64,"w":[[294.64,294.72],[294.78,294.96],[294.98,295.34],[295.4,295.72]]},{"id":58,"p":9,"en":"We don't want to bump into the person next to us.","zh":"我们不想碰到旁边的人。","s":295.64,"e":297.99,"w":[[295.76,295.82],[295.86,295.98],[295.98,296.08],[296.1,296.14],[296.2,296.4],[296.46,296.6],[296.64,296.72],[296.74,297.06],[297.1,297.36],[297.4,297.48],[297.58,297.74]]},{"id":59,"p":9,"en":"So again, both animals and humans do the same thing.","zh":"同样，动物和人类都是这样。","s":298.0,"e":300.81,"w":[[298.12,298.2],[298.28,298.56],[298.62,298.8],[298.9,299.24],[299.28,299.36],[299.4,299.72],[299.78,299.86],[299.9,299.96],[299.96,300.32],[300.36,300.56]]},{"id":60,"p":9,"en":"And this is what happens when you put together high and low power.","zh":"当高权力和低权力的人碰到一起，就会出现这样的情况。","s":301.44,"e":305.07,"w":[[301.56,301.66],[301.68,301.8],[301.86,301.94],[301.98,302.1],[302.16,302.6],[303.02,303.12],[303.14,303.22],[303.24,303.38],[303.42,303.7],[303.78,304.08],[304.14,304.22],[304.28,304.42],[304.48,304.82]]},{"id":61,"p":9,"en":"So what we tend to do when it comes to power is that we complement the other's nonverbals.","zh":"在权力这件事上，我们往往会去“互补”对方的非语言信号。","s":305.18,"e":310.83,"w":[[305.3,305.38],[305.46,305.56],[305.58,305.64],[305.73,305.93],[305.95,306.01],[306.07,306.17],[306.85,306.97],[306.99,307.05],[307.11,307.37],[307.39,307.45],[307.53,307.93],[308.07,308.15],[308.19,308.35],[308.65,308.71],[308.79,309.37],[309.41,309.49],[309.55,309.81],[309.89,310.59]]},{"id":62,"p":9,"en":"So if someone is being really powerful with us, we tend to make ourselves smaller.","zh":"如果有人在我们面前表现得非常强势，我们往往会让自己变小。","s":310.83,"e":314.71,"w":[[310.95,311.01],[311.07,311.11],[311.17,311.45],[311.45,311.49],[311.53,311.73],[311.75,311.95],[311.99,312.43],[312.47,312.61],[312.65,312.83],[313.13,313.19],[313.27,313.43],[313.45,313.51],[313.53,313.69],[313.71,314.05],[314.09,314.55]]},{"id":63,"p":9,"en":"We don't mirror them.","zh":"我们不会模仿他们。","s":314.71,"e":315.53,"w":[[314.83,314.89],[314.93,315.09],[315.15,315.39],[315.47,315.59]]},{"id":64,"p":9,"en":"We do the opposite of them.","zh":"我们会做出和他们相反的动作。","s":315.53,"e":316.94,"w":[[315.65,315.71],[315.77,315.83],[315.91,315.97],[316.07,316.41],[316.43,316.49],[316.53,316.69]]},{"id":65,"p":10,"en":"So I'm watching this behavior in the classroom, and what do I notice?","zh":"我在课堂上观察这些行为，注意到了什么？","s":317.41,"e":323.32,"w":[[317.53,317.61],[318.69,318.75],[318.81,319.13],[319.13,319.25],[319.29,319.67],[319.71,319.75],[319.75,319.83],[319.85,320.39],[321.12,321.26],[322.36,322.5],[322.52,322.58],[322.68,322.7],[322.78,323.14]]},{"id":66,"p":10,"en":"I notice that MBA students really exhibit the full range of power nonverbals.","zh":"我注意到，MBA 学生把各种权力姿态展现得淋漓尽致。","s":323.32,"e":330.44,"w":[[323.44,323.46],[323.46,323.84],[324.0,324.34],[326.2,326.46],[326.58,327.14],[327.76,327.96],[328.06,328.46],[328.5,328.58],[328.7,328.92],[329.0,329.38],[329.42,329.5],[329.56,329.84],[329.9,330.5]]},{"id":67,"p":10,"en":"So you have people who are like caricatures of alphas, really coming into the room,","zh":"有些人简直像漫画里的“头领”，一进教室，","s":330.44,"e":334.6,"w":[[330.56,330.66],[330.68,330.74],[330.74,330.84],[330.86,331.12],[331.18,331.28],[331.36,331.46],[331.48,331.64],[331.68,332.38],[332.4,332.48],[332.6,333.02],[333.3,333.5],[333.54,333.76],[333.76,333.92],[333.98,334.06],[334.14,334.38]]},{"id":68,"p":10,"en":"they get right into the middle of the room before class even starts, like they really want to occupy space.","zh":"还没上课就直接走到教室正中央，好像真的很想占据空间。","s":334.6,"e":339.84,"w":[[334.72,334.82],[334.86,334.96],[335.02,335.22],[335.22,335.34],[335.36,335.44],[335.46,335.65],[335.65,335.69],[335.69,335.75],[335.81,336.07],[336.63,336.87],[336.89,337.15],[337.23,337.37],[337.45,337.77],[337.79,337.95],[337.95,338.05],[338.11,338.33],[338.35,338.47],[338.49,338.53],[338.63,339.05],[339.13,339.59]]},{"id":69,"p":10,"en":"When they sit down, they're sort of spread out.","zh":"他们坐下时会舒展开身体。","s":340.35,"e":341.95,"w":[[340.47,340.57],[340.59,340.69],[340.77,340.93],[340.97,341.19],[341.19,341.33],[341.33,341.45],[341.45,341.51],[341.57,341.83],[341.89,342.05]]},{"id":70,"p":10,"en":"They raise their hands like this.","zh":"他们会像这样举手。","s":341.95,"e":343.56,"w":[[342.07,342.17],[342.23,342.43],[342.43,342.53],[342.57,342.79],[342.81,342.99],[343.01,343.31]]},{"id":71,"p":10,"en":"You have other people who are virtually collapsing when they come in.","zh":"另一些人进来时几乎是缩成一团。","s":344.49,"e":347.45,"w":[[344.61,344.69],[344.69,344.79],[344.85,345.03],[345.05,345.31],[345.35,345.45],[345.51,345.63],[345.69,346.09],[346.15,346.91],[346.91,347.01],[347.05,347.13],[347.19,347.41],[347.45,347.53]]},{"id":72,"p":10,"en":"As soon they come in, you see it.","zh":"他们一进门你就能看出来。","s":347.45,"e":349.19,"w":[[347.57,347.63],[347.69,347.87],[348.01,348.11],[348.15,348.33],[348.33,348.41],[348.43,348.53],[348.63,348.81],[348.85,348.97]]},{"id":73,"p":10,"en":"You see it on their faces and their bodies, and they sit in their chair and they make themselves tiny, and they go like this when they raise their hand.","zh":"从他们的脸上和身体上都看得出来，他们坐在椅子上把自己缩得很小，举手时是这样的。","s":349.19,"e":356.03,"w":[[349.31,349.39],[349.45,349.57],[349.59,349.65],[349.67,349.73],[349.75,349.87],[349.91,350.23],[350.25,350.33],[350.35,350.46],[350.5,350.92],[351.36,351.44],[351.44,351.54],[351.6,351.74],[351.78,351.82],[351.82,351.94],[351.98,352.2],[352.22,352.28],[352.28,352.38],[352.42,352.58],[352.58,352.94],[352.98,353.3],[353.84,353.92],[354.12,354.22],[354.26,354.32],[354.38,354.58],[354.6,354.8],[354.84,354.94],[354.96,355.06],[355.1,355.28],[355.3,355.4],[355.46,355.78]]},{"id":74,"p":11,"en":"I notice a couple of things about this.","zh":"我注意到了几件事。","s":356.88,"e":358.22,"w":[[357.0,357.02],[357.06,357.3],[357.34,357.36],[357.38,357.58],[357.58,357.62],[357.62,357.82],[357.84,358.0],[358.02,358.16]]},{"id":75,"p":11,"en":"One, you're not going to be surprised.","zh":"第一件，你不会感到意外。","s":358.22,"e":360.04,"w":[[358.34,358.52],[358.76,358.9],[358.9,359.0],[359.02,359.14],[359.14,359.18],[359.2,359.24],[359.32,359.86]]},{"id":76,"p":11,"en":"It seems to be related to gender.","zh":"这似乎和性别有关。","s":360.04,"e":361.95,"w":[[360.16,360.24],[360.3,360.52],[360.56,360.62],[360.66,360.72],[360.8,361.12],[361.16,361.22],[361.32,361.7]]},{"id":77,"p":11,"en":"So women are much more likely to do this kind of thing than men.","zh":"女性比男性更容易做出这种动作。","s":362.58,"e":367.36,"w":[[362.7,362.8],[364.24,364.52],[364.62,364.72],[364.76,364.94],[365.02,365.18],[365.22,365.59],[365.69,365.77],[365.81,365.89],[365.97,366.13],[366.19,366.39],[366.41,366.47],[366.53,366.69],[366.71,366.83],[366.87,367.11]]},{"id":78,"p":11,"en":"Women feel chronically less powerful than men, so this is not surprising.","zh":"女性长期以来感觉自己比男性更没有权力，所以这并不奇怪。","s":368.03,"e":372.1,"w":[[368.15,368.39],[368.53,368.73],[368.79,369.31],[369.57,369.71],[369.77,370.21],[370.23,370.35],[370.39,370.59],[370.67,370.73],[370.79,370.89],[370.93,371.01],[371.05,371.17],[371.21,371.85]]},{"id":79,"p":12,"en":"But the other thing I noticed is that it also seemed to be related to the extent to which the students were participating, and how well they were participating.","zh":"但我注意到的另一件事是，这似乎也和学生参与课堂的程度、参与得好不好有关。","s":372.16,"e":380.72,"w":[[373.09,373.19],[373.21,373.27],[373.31,373.43],[373.47,373.59],[373.67,373.69],[373.75,374.05],[374.07,374.15],[374.17,374.29],[374.33,374.41],[374.47,374.67],[374.79,374.99],[375.03,375.07],[375.11,375.17],[375.27,375.73],[376.13,376.21],[376.25,376.33],[376.37,376.81],[376.89,376.97],[377.01,377.23],[377.29,377.37],[377.41,377.71],[377.75,377.89],[377.89,378.75],[379.19,379.29],[379.35,379.51],[379.59,379.79],[379.83,379.93],[379.95,380.07],[380.07,380.8]]},{"id":80,"p":12,"en":"And this is really important in the MBA classroom, because participation counts for half the grade.","zh":"这在 MBA 课堂上非常重要，因为课堂参与占成绩的一半。","s":380.72,"e":386.13,"w":[[380.84,380.92],[380.94,381.08],[381.14,381.22],[381.38,381.66],[381.74,382.26],[382.64,382.7],[382.74,382.82],[382.92,383.14],[383.26,383.74],[383.78,384.0],[384.0,384.68],[384.76,385.02],[385.04,385.14],[385.2,385.38],[385.4,385.46],[385.52,385.88]]},{"id":81,"p":13,"en":"So business schools have been struggling with this gender grade gap.","zh":"商学院一直在为这种性别成绩差距发愁。","s":386.74,"e":390.55,"w":[[386.86,386.94],[388.0,388.28],[388.32,388.54],[388.56,388.64],[388.64,388.74],[388.78,389.14],[389.14,389.26],[389.26,389.36],[389.44,389.7],[389.76,390.0],[390.08,390.3]]},{"id":82,"p":13,"en":"You get these equally qualified women and men coming in and then you get these differences in grades, and it seems to be partly attributable to participation.","zh":"进来的男生女生条件一样好，成绩却出现了差异，而这似乎部分归因于课堂参与。","s":390.76,"e":398.98,"w":[[390.88,390.96],[390.98,391.1],[391.14,391.34],[391.46,391.74],[391.8,392.26],[392.28,392.5],[392.54,392.62],[392.64,392.8],[392.88,393.2],[393.24,393.4],[394.52,394.6],[394.62,394.74],[394.76,394.84],[394.86,394.98],[395.02,395.21],[395.23,395.65],[395.69,395.75],[395.79,396.19],[396.21,396.29],[396.29,396.35],[396.41,396.63],[396.67,396.73],[396.75,396.81],[396.89,397.19],[397.23,397.81],[397.85,397.91],[397.95,398.73]]},{"id":83,"p":13,"en":"So I started to wonder, you know, okay, so you have these people coming in like this, and they're participating.","zh":"于是我开始想：好吧，有些人是这样进来的，而且他们积极参与。","s":399.25,"e":405.72,"w":[[399.37,399.45],[399.67,399.69],[399.73,400.03],[400.07,400.13],[400.23,400.61],[401.15,401.23],[401.23,401.37],[401.49,401.79],[402.41,402.47],[402.51,402.57],[402.63,402.81],[402.81,403.01],[403.03,403.33],[403.53,403.83],[403.85,403.93],[403.97,404.15],[404.19,404.43],[404.49,404.55],[404.55,404.69],[404.69,405.47]]},{"id":84,"p":13,"en":"Is it possible that we could get people to fake it and would it lead them to participate more?","zh":"有没有可能让人们“装”出来，而这又会让他们参与得更多？","s":405.73,"e":410.38,"w":[[405.85,405.93],[405.97,406.03],[406.07,406.61],[406.65,406.75],[406.77,406.83],[406.87,406.99],[407.03,407.17],[407.23,407.47],[407.49,407.53],[407.69,407.99],[408.03,408.19],[408.63,408.71],[408.73,408.85],[408.85,408.93],[409.03,409.31],[409.37,409.51],[409.57,409.63],[409.67,410.22],[410.24,410.44]]},{"id":85,"p":14,"en":"So my main collaborator Dana Carney, who's at Berkeley, and I really wanted to know, can you fake it till you make it?","zh":"我的主要合作者、伯克利的达娜·卡尼和我，都非常想知道：你能不能“假装直到成功”？","s":410.38,"e":418.69,"w":[[410.5,410.58],[411.24,411.36],[411.42,411.6],[411.88,412.42],[412.48,412.7],[412.74,413.08],[414.0,414.14],[414.18,414.24],[414.28,414.66],[415.16,415.26],[415.42,415.44],[415.68,415.9],[415.96,416.2],[416.24,416.3],[416.34,416.6],[417.06,417.18],[417.22,417.3],[417.4,417.64],[417.66,417.72],[417.76,417.88],[417.9,417.98],[418.04,418.28],[418.32,418.44]]},{"id":86,"p":14,"en":"Like, can you do this just for a little while and actually experience a behavioral outcome that makes you seem more powerful?","zh":"比如，你能不能只这样做一小会儿，就真的产生一种让你显得更有力量的行为结果？","s":418.84,"e":424.94,"w":[[418.96,419.1],[419.1,419.2],[419.24,419.3],[419.34,419.4],[419.44,419.56],[419.6,419.76],[419.78,419.84],[419.88,419.9],[419.94,420.12],[420.2,420.56],[421.1,421.2],[421.26,421.6],[422.0,422.6],[422.66,422.68],[422.74,423.2],[423.32,423.66],[423.68,423.76],[423.8,423.96],[424.0,424.06],[424.12,424.26],[424.3,424.42],[424.44,424.94]]},{"id":87,"p":14,"en":"So we know that our nonverbals govern how other people think and feel about us.","zh":"我们知道，我们的非语言信号支配着别人对我们的想法和感受。","s":424.94,"e":429.79,"w":[[425.55,425.63],[425.79,425.87],[425.97,426.21],[426.33,426.47],[426.51,426.59],[426.65,427.35],[427.81,428.11],[428.17,428.31],[428.49,428.69],[428.73,428.99],[429.03,429.17],[429.23,429.31],[429.35,429.53],[429.57,429.79],[429.81,429.87]]},{"id":88,"p":14,"en":"There's a lot of evidence.","zh":"这方面有很多证据。","s":429.79,"e":430.71,"w":[[429.91,430.05],[430.07,430.09],[430.15,430.29],[430.31,430.35],[430.43,430.81]]},{"id":89,"p":14,"en":"But our question really was, do our nonverbals govern how we think and feel about ourselves?","zh":"但我们真正的问题是：我们的非语言信号会不会支配我们对自己的想法和感受？","s":430.71,"e":436.3,"w":[[430.83,430.91],[430.95,431.03],[431.07,431.43],[431.49,431.69],[431.77,432.03],[432.73,432.83],[433.13,433.23],[433.29,433.99],[434.11,434.43],[434.53,434.65],[434.69,434.77],[434.83,434.99],[435.03,435.11],[435.13,435.31],[435.33,435.51],[435.53,436.05]]},{"id":90,"p":15,"en":"There's some evidence that they do.","zh":"有一些证据表明会。","s":437.65,"e":439.35,"w":[[437.77,437.95],[438.03,438.23],[438.31,438.69],[438.73,438.87],[438.91,439.03],[439.07,439.17]]},{"id":91,"p":15,"en":"So, for example, we smile when we feel happy, but also, when we're forced to smile by holding a pen in our teeth like this, it makes us feel happy.","zh":"比如，我们开心时会微笑；但当我们像这样用牙齿咬住一支笔、被迫“微笑”时，也会让我们感到开心。","s":439.35,"e":450.51,"w":[[439.47,439.57],[440.44,440.54],[440.56,442.24],[442.76,442.84],[442.96,443.3],[443.32,443.42],[443.46,443.52],[443.6,443.76],[443.84,444.16],[444.32,444.44],[444.54,444.78],[444.84,444.94],[444.98,445.14],[445.18,445.48],[445.5,445.54],[445.62,446.04],[446.18,446.28],[446.36,446.72],[446.86,446.88],[446.94,447.14],[447.2,447.26],[447.32,447.4],[447.44,447.64],[447.66,447.84],[447.84,448.06],[449.36,449.44],[449.46,449.64],[449.7,449.76],[449.8,449.9],[449.96,450.26]]},{"id":92,"p":15,"en":"So it goes both ways.","zh":"所以这是双向的。","s":451.06,"e":452.53,"w":[[451.18,451.26],[451.38,451.44],[451.48,451.66],[451.72,451.9],[451.96,452.28]]},{"id":93,"p":15,"en":"When it comes to power, it also goes both ways.","zh":"在权力这件事上，也是双向的。","s":452.6,"e":456.55,"w":[[452.72,452.84],[452.86,452.92],[452.94,453.14],[453.18,453.24],[453.3,453.7],[455.09,455.17],[455.23,455.45],[455.53,455.73],[455.79,455.97],[456.03,456.33]]},{"id":94,"p":15,"en":"So when you feel powerful, you're more likely to do this, but it's also possible that when you pretend to be powerful, you are more likely to actually feel powerful.","zh":"当你感到有力量时，你更可能这样做；但也有可能，当你假装有力量时，你真的会更觉得自己有力量。","s":456.55,"e":470.33,"w":[[456.67,456.75],[457.63,457.75],[457.81,457.93],[458.53,458.75],[458.79,459.21],[459.25,459.41],[459.41,459.57],[459.59,459.83],[459.89,459.95],[460.01,460.11],[460.19,460.43],[460.83,460.93],[460.97,461.09],[461.13,461.33],[461.41,461.95],[462.51,462.73],[464.17,464.31],[464.37,464.47],[465.39,465.81],[465.85,465.93],[465.95,466.03],[466.11,466.65],[467.07,467.19],[467.39,467.55],[467.79,467.97],[468.01,468.37],[468.79,468.89],[469.03,469.31],[469.39,469.59],[469.63,470.08]]},{"id":95,"p":16,"en":"So the second question really was, you know, so we know that our minds change our bodies, but is it also true that our bodies change our minds?","zh":"所以第二个问题是：我们知道心灵会改变身体，那身体是否也会改变心灵？","s":471.06,"e":480.15,"w":[[471.18,471.24],[471.34,471.4],[471.46,471.72],[471.74,472.06],[472.12,472.34],[472.5,472.74],[473.1,473.16],[473.16,473.28],[474.0,474.08],[474.26,474.32],[474.38,474.56],[474.6,474.72],[474.8,474.88],[474.94,475.28],[475.36,475.62],[475.66,475.74],[475.78,476.24],[476.44,476.76],[476.76,476.84],[476.86,476.92],[477.0,477.24],[477.34,477.6],[477.94,478.08],[478.18,478.28],[478.34,478.76],[479.02,479.3],[479.34,479.42],[479.46,479.9]]},{"id":96,"p":16,"en":"And when I say minds, in the case of the powerful, what am I talking about?","zh":"说到有权力者的“心灵”，我指的是什么？","s":480.94,"e":484.41,"w":[[481.06,481.16],[481.18,481.3],[481.38,481.4],[481.5,481.68],[481.78,482.16],[482.22,482.28],[482.28,482.36],[482.38,482.6],[482.62,482.68],[482.7,482.76],[482.78,483.18],[483.22,483.32],[483.34,483.44],[483.48,483.5],[483.56,483.9],[483.92,484.16]]},{"id":97,"p":16,"en":"So I'm talking about thoughts and feelings and the sort of physiological things that make up our thoughts and feelings, and in my case, that's hormones.","zh":"我指的是想法、感受，以及构成想法和感受的那些生理因素，在我的研究里，就是激素。","s":484.65,"e":492.3,"w":[[484.77,484.81],[484.81,484.89],[484.93,485.19],[485.21,485.39],[485.47,485.85],[486.55,486.67],[486.73,487.25],[487.35,487.43],[487.45,487.51],[487.57,487.71],[487.73,487.77],[487.91,488.63],[488.69,488.89],[488.91,489.03],[489.11,489.31],[489.33,489.41],[489.77,489.87],[489.89,490.13],[490.15,490.25],[490.27,490.57],[490.59,490.65],[490.65,490.71],[490.73,490.89],[490.95,491.17],[491.21,491.39],[491.49,492.05]]},{"id":98,"p":16,"en":"I look at hormones.","zh":"我研究激素。","s":492.35,"e":493.48,"w":[[492.47,492.49],[492.53,492.65],[492.65,492.73],[492.77,493.23]]},{"id":99,"p":16,"en":"So what do the minds of the powerful versus the powerless look like?","zh":"那么，有权力和没权力的人，心灵是什么样的？","s":493.69,"e":497.8,"w":[[493.81,493.89],[493.99,494.15],[494.23,494.31],[494.37,494.45],[494.49,494.85],[494.89,494.95],[494.97,495.05],[495.09,495.69],[496.15,496.43],[496.45,496.53],[496.57,497.01],[497.11,497.25],[497.29,497.55]]},{"id":100,"p":16,"en":"So powerful people tend to be, not surprisingly, more assertive and more confident, more optimistic.","zh":"不出所料，有权力的人往往更果断、更自信、更乐观。","s":498.25,"e":506.3,"w":[[498.37,498.45],[498.61,499.05],[499.11,499.45],[500.54,500.76],[500.82,500.88],[500.94,501.04],[501.46,501.6],[501.64,502.16],[502.22,502.38],[502.38,502.92],[503.38,503.48],[503.5,503.64],[503.68,504.28],[505.32,505.48],[505.56,506.26]]},{"id":101,"p":16,"en":"They actually feel they're going to win even at games of chance.","zh":"他们甚至在靠运气的游戏里都觉得自己会赢。","s":506.3,"e":509.29,"w":[[506.42,506.52],[506.56,506.82],[506.92,507.14],[507.24,507.42],[507.42,507.54],[507.54,507.58],[507.62,507.78],[507.9,508.06],[508.1,508.16],[508.2,508.42],[508.46,508.52],[508.58,509.04]]},{"id":102,"p":16,"en":"They also tend to be able to think more abstractly.","zh":"他们也往往更能进行抽象思考。","s":509.58,"e":513.34,"w":[[509.7,510.66],[510.78,511.08],[511.5,511.68],[511.7,511.76],[511.78,511.84],[511.9,512.08],[512.1,512.16],[512.24,512.42],[512.48,512.62],[512.68,513.36]]},{"id":103,"p":16,"en":"So there are a lot of differences.","zh":"所以差别很多。","s":513.34,"e":515.04,"w":[[513.46,513.54],[513.58,513.7],[513.7,513.76],[513.76,513.78],[513.82,513.98],[514.0,514.08],[514.16,514.79]]},{"id":104,"p":16,"en":"They take more risks.","zh":"他们更敢冒险。","s":515.05,"e":515.99,"w":[[515.17,515.29],[515.33,515.53],[515.55,515.69],[515.75,516.09]]},{"id":105,"p":16,"en":"There are a lot of differences between powerful and powerless people.","zh":"有权力和没权力的人之间有很多差别。","s":515.99,"e":518.82,"w":[[516.11,516.23],[516.23,516.29],[516.29,516.31],[516.33,516.45],[516.47,516.53],[516.57,516.95],[516.99,517.27],[517.31,517.71],[517.73,517.81],[517.81,518.21],[518.27,518.57]]},{"id":106,"p":16,"en":"Physiologically, there also are differences on two key hormones: testosterone, which is the dominance hormone, and cortisol, which is the stress hormone.","zh":"从生理上看，两种关键激素也有差别：睾酮，也就是“支配激素”；还有皮质醇，也就是“压力激素”。","s":519.23,"e":529.34,"w":[[519.35,520.21],[520.79,520.97],[521.05,521.27],[521.35,521.45],[521.49,521.99],[522.11,522.21],[522.29,522.55],[523.19,523.37],[523.45,523.97],[524.67,525.27],[525.29,525.41],[525.43,525.51],[525.53,525.61],[525.65,526.07],[526.13,526.57],[527.29,527.39],[527.43,527.91],[527.93,528.07],[528.11,528.17],[528.21,528.29],[528.33,528.61],[528.67,529.09]]},{"id":107,"p":17,"en":"So what we find is that high-power alpha males in primate hierarchies have high testosterone and low cortisol, and","zh":"我们发现，灵长类群体等级中处于高位的头领雄性，睾酮高、皮质醇低，","s":529.92,"e":540.95,"w":[[530.04,530.14],[531.0,531.12],[531.14,531.22],[531.3,531.66],[531.76,531.88],[531.92,532.16],[534.3,534.6],[534.78,535.16],[535.64,535.88],[535.94,536.24],[536.28,536.34],[536.4,536.82],[536.84,537.46],[537.5,537.64],[537.7,537.92],[537.94,538.68],[538.72,538.82],[538.88,539.02],[539.08,539.58],[540.48,540.7]]},{"id":108,"p":17,"en":"powerful and effective leaders also have high testosterone and low cortisol.","zh":"强大而高效的领导者也是睾酮高、皮质醇低。","s":541.3,"e":546.48,"w":[[541.42,542.0],[542.08,542.18],[542.2,542.74],[542.78,543.12],[543.4,543.7],[543.82,543.98],[544.02,544.25],[544.27,545.05],[545.41,545.51],[545.55,545.67],[545.73,546.23]]},{"id":109,"p":17,"en":"So what does that mean?","zh":"这意味着什么？","s":546.51,"e":547.74,"w":[[546.63,546.71],[546.77,546.91],[546.93,547.07],[547.07,547.23],[547.27,547.49]]},{"id":110,"p":17,"en":"When you think about power, people tended to think only about testosterone, because that was about dominance.","zh":"一想到权力，人们往往只想到睾酮，因为它和支配有关。","s":547.77,"e":552.74,"w":[[547.89,547.99],[548.05,548.13],[548.15,548.29],[548.33,548.51],[548.55,548.83],[549.13,549.35],[549.39,549.65],[549.69,549.73],[549.79,549.95],[550.03,550.19],[550.25,550.43],[550.45,550.97],[550.97,551.13],[551.13,551.23],[551.25,551.35],[551.61,551.85],[551.89,552.49]]},{"id":111,"p":17,"en":"But really, power is also about how you react to stress.","zh":"但其实，权力也关乎你如何应对压力。","s":552.83,"e":556.02,"w":[[552.95,553.09],[553.15,553.37],[553.45,553.75],[553.83,553.91],[553.99,554.21],[554.31,554.55],[554.59,554.71],[554.75,554.85],[554.89,555.19],[555.21,555.25],[555.33,555.77]]},{"id":112,"p":17,"en":"So do you want the high-power leader that's dominant, high on testosterone, but really stress reactive?","zh":"你想要一个强势、睾酮很高、但对压力反应很大的领导者吗？","s":556.11,"e":562.2,"w":[[556.23,556.31],[556.39,556.45],[556.51,556.61],[556.65,556.83],[556.97,557.05],[557.13,557.39],[557.41,557.69],[557.79,558.09],[558.67,558.87],[558.95,559.48],[559.56,559.74],[559.76,559.82],[559.84,560.56],[560.6,560.72],[560.94,561.2],[561.3,561.6],[561.7,562.24]]},{"id":113,"p":17,"en":"Probably not, right?","zh":"大概不想吧？","s":562.2,"e":563.3,"w":[[562.32,562.74],[562.82,563.08],[563.18,563.36]]},{"id":114,"p":17,"en":"You want the person who's powerful and assertive and dominant, but not very stress reactive, the person who's laid back.","zh":"你想要的是一个有力量、果断、强势，但对压力不那么敏感、从容淡定的人。","s":563.3,"e":569.86,"w":[[563.42,563.52],[563.56,563.74],[563.78,563.86],[563.9,564.32],[564.74,564.88],[564.96,565.52],[565.64,565.72],[565.72,566.22],[566.24,566.34],[566.36,566.86],[567.24,567.34],[567.44,567.64],[567.72,567.88],[567.94,568.18],[568.28,568.68],[568.7,568.76],[568.78,569.06],[569.08,569.24],[569.34,569.54],[569.6,569.86]]},{"id":115,"p":18,"en":"So we know that in primate hierarchies, if an alpha needs to take over, if an individual needs to take over an alpha role sort of suddenly,","zh":"我们知道，在灵长类群体中，如果某个个体需要突然接替头领的角色，","s":569.86,"e":582.06,"w":[[570.44,570.52],[571.6,571.66],[571.72,571.9],[572.02,572.2],[573.84,573.9],[573.96,574.35],[574.37,574.99],[575.57,575.71],[575.89,575.97],[576.09,576.37],[576.93,577.17],[577.23,577.31],[577.39,577.69],[577.79,578.09],[579.23,579.31],[579.35,579.43],[579.49,579.81],[579.83,579.97],[579.99,580.05],[580.11,580.29],[580.31,580.45],[580.47,580.51],[580.57,580.77],[580.85,581.07],[581.13,581.27],[581.27,581.35],[581.43,581.81]]},{"id":116,"p":18,"en":"within a few days, that individual's testosterone has gone up significantly and his cortisol has dropped significantly.","zh":"短短几天内，它的睾酮会显著上升，皮质醇会显著下降。","s":582.63,"e":589.12,"w":[[582.75,582.99],[583.03,583.05],[583.11,583.27],[583.35,583.69],[583.87,584.07],[584.17,584.67],[584.69,585.35],[585.39,585.53],[585.59,585.79],[585.81,585.89],[585.95,586.61],[587.07,587.13],[587.15,587.23],[587.29,587.73],[587.77,587.89],[587.95,588.23],[588.25,588.87]]},{"id":117,"p":18,"en":"So we have this evidence, both that the body can shape the mind, at least at the facial level, and also that role changes can shape the mind.","zh":"所以我们有这样的证据：身体能塑造心灵，至少在面部表情层面如此；角色的变化也能塑造心灵。","s":589.26,"e":598.93,"w":[[589.38,589.44],[589.5,589.56],[589.64,589.84],[589.86,589.98],[590.12,590.66],[591.1,591.32],[591.4,591.52],[591.56,591.62],[591.68,591.98],[592.1,592.28],[592.38,592.58],[592.6,592.68],[592.72,592.94],[592.96,593.02],[593.06,593.22],[593.26,593.3],[593.32,593.38],[593.44,593.76],[593.8,594.08],[595.48,595.58],[595.68,595.98],[596.52,596.7],[596.86,597.14],[597.18,597.68],[597.74,597.88],[597.96,598.18],[598.2,598.28],[598.3,598.68]]},{"id":118,"p":18,"en":"So what happens, okay, you take a role change, what happens if you do that at a really minimal level, like this tiny manipulation, this tiny intervention?","zh":"那么，如果你只在极小的程度上改变角色，比如做一个很小的操纵、很小的干预，会怎么样？","s":598.98,"e":607.03,"w":[[599.1,599.18],[599.26,599.4],[599.48,599.84],[599.86,599.98],[600.04,600.12],[600.18,600.38],[600.48,600.5],[600.62,600.88],[600.96,601.42],[602.56,602.66],[602.7,602.98],[603.0,603.06],[603.1,603.18],[603.18,603.24],[603.28,603.42],[603.48,603.54],[603.56,603.58],[603.66,603.88],[603.95,604.23],[604.29,604.49],[604.53,604.67],[604.67,604.79],[604.83,605.13],[605.21,605.77],[605.79,605.91],[605.95,606.21],[606.29,606.81]]},{"id":119,"p":18,"en":"\"For two minutes,\" you say, \"I want you to stand like this, and it's going to make you feel more powerful.\"","zh":"你说：“请你像这样站两分钟，它会让你觉得更有力量。”","s":607.03,"e":611.46,"w":[[607.15,607.27],[607.33,607.51],[607.57,607.83],[607.87,607.95],[608.01,608.21],[608.73,608.75],[608.79,608.93],[608.97,609.05],[609.05,609.11],[609.15,609.41],[609.43,609.59],[609.61,609.75],[609.79,609.87],[609.89,609.97],[609.99,610.11],[610.13,610.17],[610.19,610.35],[610.35,610.43],[610.43,610.57],[610.59,610.71],[610.73,611.21]]},{"id":120,"p":19,"en":"So this is what we did.","zh":"这就是我们做的事。","s":612.43,"e":614.86,"w":[[612.55,612.63],[613.81,613.95],[613.99,614.07],[614.11,614.21],[614.25,614.31],[614.39,614.61]]},{"id":121,"p":19,"en":"We decided to bring people into the lab and run a little experiment, and these people adopted, for two minutes,","zh":"我们决定把人们请进实验室做个小实验，这些人保持两分钟的","s":615.07,"e":622.99,"w":[[615.19,615.25],[615.31,615.75],[615.81,615.91],[616.27,616.43],[616.45,616.69],[616.73,616.87],[616.87,616.99],[617.05,617.35],[617.95,618.15],[618.31,618.43],[618.45,618.47],[618.51,618.67],[618.69,619.34],[619.82,620.0],[620.26,620.42],[620.44,620.74],[621.28,621.78],[621.84,621.96],[622.04,622.28],[622.36,622.74]]},{"id":122,"p":19,"en":"either high-power poses or low-power poses, and I'm just going to show you five of the poses, although they took on only two.","zh":"高权力姿势或低权力姿势。我给大家看其中五种姿势，不过他们只做了两种。","s":623.22,"e":630.17,"w":[[623.34,623.76],[624.4,624.62],[624.64,624.9],[624.96,625.42],[625.58,625.66],[625.74,625.88],[625.96,626.2],[626.24,626.62],[626.66,626.74],[626.76,626.82],[626.84,626.96],[626.98,627.1],[627.1,627.14],[627.22,627.38],[627.44,627.54],[627.7,628.04],[628.06,628.12],[628.14,628.24],[628.28,628.62],[628.7,628.92],[628.94,629.04],[629.1,629.26],[629.3,629.4],[629.48,629.64],[629.72,629.92]]},{"id":123,"p":19,"en":"So here's one.","zh":"这是第一种。","s":630.78,"e":631.91,"w":[[630.9,630.98],[631.08,631.3],[631.46,631.66]]},{"id":124,"p":19,"en":"A couple more.","zh":"再看几种。","s":633.44,"e":634.46,"w":[[633.56,633.58],[633.62,633.87],[633.93,634.21]]},{"id":125,"p":19,"en":"This one has been dubbed the \"Wonder Woman\" by the media.","zh":"这一种被媒体称作“神奇女侠”。","s":635.29,"e":639.14,"w":[[635.41,635.55],[635.65,635.77],[635.83,635.97],[636.01,636.17],[636.39,636.67],[636.77,636.87],[637.21,637.45],[637.49,637.73],[638.23,638.37],[638.53,638.59],[638.63,638.89]]},{"id":126,"p":19,"en":"Here are a couple more.","zh":"还有几种。","s":640.19,"e":641.24,"w":[[640.31,640.39],[640.39,640.45],[640.47,640.49],[640.51,640.71],[640.77,640.99]]},{"id":127,"p":19,"en":"So you can be standing or you can be sitting.","zh":"可以站着，也可以坐着。","s":641.69,"e":643.8,"w":[[641.81,641.85],[641.89,641.97],[641.97,642.07],[642.09,642.15],[642.27,642.67],[642.73,642.83],[642.87,642.95],[642.97,643.07],[643.09,643.13],[643.23,643.55]]},{"id":128,"p":19,"en":"And here are the low-power poses.","zh":"下面是低权力姿势。","s":644.41,"e":645.81,"w":[[644.53,644.61],[644.63,644.73],[644.73,644.79],[644.81,644.89],[644.93,645.03],[645.09,645.31],[645.41,645.79]]},{"id":129,"p":19,"en":"So you're folding up, you're making yourself small.","zh":"你在把自己折起来，让自己变小。","s":645.81,"e":648.08,"w":[[645.93,646.01],[646.07,646.21],[646.23,646.57],[646.61,646.71],[646.73,646.87],[646.87,647.11],[647.13,647.43],[647.51,647.83]]},{"id":130,"p":19,"en":"This one is very low-power.","zh":"这一种权力感非常低。","s":650.26,"e":651.92,"w":[[650.38,650.54],[650.62,650.72],[650.76,650.82],[651.02,651.3],[651.4,651.5],[651.58,651.88]]},{"id":131,"p":19,"en":"When you're touching your neck, you're really protecting yourself.","zh":"当你摸着脖子时，其实是在保护自己。","s":651.92,"e":655.21,"w":[[652.04,652.14],[652.16,652.28],[652.28,652.62],[652.64,652.74],[652.78,653.0],[653.38,653.52],[653.56,653.8],[654.12,654.56],[654.6,654.96]]},{"id":132,"p":20,"en":"So this is what happens.","zh":"实验是这样进行的。","s":655.76,"e":657.71,"w":[[655.88,656.0],[656.68,656.8],[656.84,656.92],[656.94,657.04],[657.06,657.46]]},{"id":133,"p":20,"en":"They come in, they spit into a vial, for two minutes, we say, \"You need to do this or this.\"","zh":"他们进来，往小瓶子里吐口水，然后两分钟，我们说：“你要做这个动作或那个动作。”","s":657.72,"e":662.97,"w":[[657.84,657.96],[658.0,658.2],[658.24,658.38],[658.68,658.78],[658.82,659.0],[659.04,659.2],[659.26,659.28],[659.34,659.68],[660.54,660.66],[660.7,660.86],[660.92,661.2],[661.24,661.28],[661.3,661.48],[661.64,661.72],[661.74,661.88],[661.9,661.96],[662.0,662.06],[662.14,662.3],[662.36,662.42],[662.46,662.72]]},{"id":134,"p":20,"en":"They don't look at pictures of the poses.","zh":"他们不看姿势的图片。","s":663.04,"e":664.39,"w":[[663.16,663.26],[663.28,663.42],[663.42,663.55],[663.57,663.61],[663.65,663.97],[663.97,664.03],[664.03,664.11],[664.15,664.47]]},{"id":135,"p":20,"en":"We don't want to prime them with a concept of power.","zh":"我们不想用“权力”的概念去暗示他们。","s":664.39,"e":666.64,"w":[[664.51,664.55],[664.59,664.69],[664.69,664.77],[664.79,664.83],[664.87,665.21],[665.23,665.33],[665.37,665.47],[665.51,665.53],[665.57,665.93],[665.97,666.03],[666.05,666.39]]},{"id":136,"p":20,"en":"We want them to be feeling power.","zh":"我们希望他们去“感受”权力。","s":666.65,"e":668.66,"w":[[666.77,666.83],[666.89,667.05],[667.07,667.17],[667.21,667.27],[667.31,667.39],[667.53,667.99],[668.05,668.41]]},{"id":137,"p":20,"en":"So two minutes they do this.","zh":"他们就这样做两分钟。","s":668.73,"e":670.26,"w":[[668.85,668.93],[669.01,669.17],[669.19,669.43],[669.45,669.55],[669.59,669.67],[669.77,670.01]]},{"id":138,"p":20,"en":"We then ask them, \"How powerful do you feel?\" on a series of items, and then we give them an opportunity to gamble, and then we take another saliva sample.","zh":"接着我们用一系列问题问他们“你觉得自己有多有力量？”，然后给他们一个赌一把的机会，再采集一次唾液样本。","s":670.63,"e":679.26,"w":[[670.75,670.81],[670.85,670.99],[671.09,671.27],[671.31,671.47],[671.77,671.91],[671.95,672.31],[672.35,672.39],[672.41,672.49],[672.53,672.73],[672.77,672.83],[672.87,672.89],[672.95,673.21],[673.23,673.29],[673.43,673.81],[674.27,674.39],[674.41,674.57],[674.69,674.77],[674.83,674.99],[674.99,675.09],[675.13,675.17],[675.25,675.77],[675.85,675.91],[675.99,676.39],[677.15,677.27],[677.31,677.53],[677.81,677.91],[678.13,678.31],[678.33,678.54],[678.58,678.92],[678.98,679.28]]},{"id":139,"p":20,"en":"That's it.","zh":"就这些。","s":679.26,"e":679.64,"w":[[679.38,679.6],[679.68,679.74]]},{"id":140,"p":20,"en":"That's the whole experiment.","zh":"这就是整个实验。","s":679.64,"e":681.09,"w":[[679.76,679.94],[679.96,680.04],[680.06,680.24],[680.26,680.84]]},{"id":141,"p":21,"en":"So this is what we find.","zh":"我们的发现是这样的。","s":681.16,"e":682.57,"w":[[681.28,681.34],[681.4,681.52],[681.54,681.6],[681.64,681.74],[681.78,681.84],[681.94,682.32]]},{"id":142,"p":21,"en":"Risk tolerance, which is the gambling, we find that when you are in the high-power pose condition, 86 percent of you will gamble.","zh":"在冒险容忍度，也就是赌博这一项上，我们发现做了高权力姿势的人，86% 会选择赌一把。","s":682.6,"e":691.07,"w":[[682.72,682.92],[682.98,683.5],[683.5,683.64],[683.68,683.76],[683.78,683.86],[683.92,684.46],[685.04,685.2],[685.26,685.5],[685.64,685.78],[686.66,686.76],[686.76,686.82],[686.82,686.88],[686.88,686.92],[686.92,686.98],[687.04,687.24],[687.26,687.48],[687.6,687.8],[687.82,688.28],[688.78,688.92],[689.0,689.1],[689.18,689.58],[689.62,689.68],[689.74,689.88],[690.28,690.4],[690.42,690.82]]},{"id":143,"p":21,"en":"When you're in the low-power pose condition, only 60 percent, and that's a whopping significant difference.","zh":"做了低权力姿势的人只有 60%，这个差别非常显著。","s":691.2,"e":696.27,"w":[[691.32,691.46],[691.74,691.86],[691.9,691.96],[691.98,692.04],[692.1,692.22],[692.3,692.52],[692.54,692.78],[692.78,693.12],[693.2,693.34],[693.45,693.71],[693.77,694.13],[694.21,694.29],[694.31,694.47],[694.53,694.55],[694.99,695.33],[695.37,695.81],[695.85,696.27]]},{"id":144,"p":22,"en":"Here's what we find on testosterone.","zh":"再看睾酮的结果。","s":696.27,"e":698.74,"w":[[697.03,697.17],[697.19,697.27],[697.29,697.33],[697.39,697.59],[697.61,697.67],[697.71,698.49]]},{"id":145,"p":22,"en":"From their baseline when they come in, high-power people experience about a 20-percent increase, and low-power people experience about a 10-percent decrease.","zh":"和刚进来时的基线相比，高权力组的睾酮上升了大约 20%，低权力组下降了大约 10%。","s":699.49,"e":709.88,"w":[[699.61,699.79],[700.03,700.17],[700.23,700.67],[700.67,700.77],[700.79,700.89],[700.95,701.15],[701.19,701.33],[702.03,702.21],[702.21,702.45],[702.49,702.81],[702.91,703.31],[703.33,703.47],[703.49,703.51],[703.57,703.85],[703.91,704.23],[704.35,704.87],[706.27,706.39],[706.45,706.55],[706.61,706.85],[706.91,707.25],[707.77,708.21],[708.23,708.4],[708.4,708.42],[708.48,708.66],[708.7,709.02],[709.1,709.68]]},{"id":146,"p":22,"en":"So again, two minutes, and you get these changes.","zh":"再说一遍，只要两分钟，就有这些变化。","s":709.88,"e":712.45,"w":[[710.0,710.06],[710.14,710.32],[710.4,710.6],[710.64,710.96],[711.08,711.18],[711.2,711.28],[711.28,711.4],[711.44,711.62],[711.68,712.2]]},{"id":147,"p":22,"en":"Here's what you get on cortisol.","zh":"再看皮质醇。","s":712.78,"e":714.33,"w":[[712.9,713.1],[713.12,713.22],[713.24,713.32],[713.34,713.44],[713.46,713.54],[713.6,714.08]]},{"id":148,"p":22,"en":"High-power people experience about a 25-percent decrease, and the low-power people experience about a 15-percent increase.","zh":"高权力组的皮质醇下降了大约 25%，低权力组则上升了大约 15%。","s":714.74,"e":722.42,"w":[[714.86,715.06],[715.08,715.32],[715.4,715.68],[715.76,716.18],[716.18,716.34],[716.36,716.38],[716.44,716.74],[716.82,717.06],[717.06,717.38],[717.42,718.0],[719.06,719.16],[719.16,719.22],[719.28,719.38],[719.46,719.72],[719.78,720.0],[720.12,720.64],[720.7,720.86],[720.88,720.9],[720.96,721.3],[721.36,721.68],[721.86,722.42]]},{"id":149,"p":22,"en":"So two minutes lead to these hormonal changes that configure your brain to basically be either assertive, confident and comfortable, or really stress-reactive, and feeling sort of shut down.","zh":"所以两分钟就能带来激素变化，让你的大脑要么变得果断、自信、自在，要么对压力反应强烈、像是关闭了一样。","s":722.42,"e":736.11,"w":[[722.88,722.96],[723.08,723.29],[723.35,723.65],[723.75,723.97],[724.05,724.11],[724.15,724.33],[724.37,724.83],[724.87,725.43],[725.77,725.89],[725.93,726.43],[726.47,726.59],[726.63,726.99],[727.07,727.13],[727.21,727.67],[727.75,727.83],[728.09,728.41],[729.05,729.69],[730.05,730.55],[730.55,730.65],[730.67,731.29],[731.93,732.07],[732.41,732.65],[732.75,733.07],[733.17,733.81],[734.67,734.83],[735.15,735.47],[735.49,735.63],[735.67,735.71],[735.79,735.97],[736.01,736.21]]},{"id":150,"p":22,"en":"And we've all had the feeling, right?","zh":"我们都有过这种感觉，对吧？","s":736.11,"e":738.51,"w":[[736.23,736.31],[736.31,736.47],[736.55,736.69],[736.85,737.03],[737.07,737.15],[737.39,737.79],[737.99,738.26]]},{"id":151,"p":22,"en":"So it seems that our nonverbals do govern how we think and feel about ourselves, so it's not just others, but it's also ourselves.","zh":"看来我们的非语言信号确实支配着我们对自己的想法和感受，所以不只是别人，也包括我们自己。","s":739.24,"e":746.87,"w":[[739.36,739.44],[740.1,740.18],[740.26,740.56],[740.6,740.76],[740.88,740.98],[741.02,741.64],[741.86,741.98],[742.14,742.52],[742.82,742.94],[743.0,743.06],[743.14,743.28],[743.34,743.42],[743.46,743.62],[743.66,743.84],[743.86,744.28],[744.32,744.38],[744.46,744.54],[744.58,744.72],[744.76,744.96],[745.08,745.34],[745.4,745.48],[745.52,745.62],[745.72,745.94],[746.1,746.62]]},{"id":152,"p":22,"en":"Also, our bodies change our minds.","zh":"而且，我们的身体会改变我们的心灵。","s":747.34,"e":749.39,"w":[[747.46,747.72],[747.9,748.0],[748.02,748.32],[748.38,748.6],[748.64,748.72],[748.74,749.14]]},{"id":153,"p":23,"en":"But the next question, of course, is, can power posing for a few minutes really change your life in meaningful ways?","zh":"但下一个问题当然是：摆几分钟的权力姿势，真的能以有意义的方式改变你的人生吗？","s":749.92,"e":755.85,"w":[[750.04,750.12],[750.14,750.22],[750.24,750.46],[750.5,750.82],[750.84,750.92],[750.98,751.26],[751.3,751.42],[751.82,751.96],[752.02,752.26],[752.34,752.66],[752.68,752.78],[752.82,752.84],[752.88,753.07],[753.13,753.39],[753.63,753.95],[754.09,754.39],[754.41,754.51],[754.55,754.83],[754.89,754.97],[755.05,755.53],[755.57,755.87]]},{"id":154,"p":23,"en":"This is in the lab, it's this little task, it's just a couple of minutes.","zh":"这是在实验室里，只是一个小任务，只有几分钟。","s":755.85,"e":759.56,"w":[[755.97,756.09],[756.13,756.21],[756.25,756.31],[756.33,756.39],[756.47,756.79],[756.85,756.93],[756.93,757.03],[757.07,757.25],[757.29,757.85],[758.19,758.39],[758.41,758.53],[758.55,758.57],[758.59,758.79],[758.81,758.87],[758.93,759.31]]},{"id":155,"p":23,"en":"Where can you actually apply this?","zh":"那在现实中能用在哪里呢？","s":759.91,"e":761.51,"w":[[760.03,760.23],[760.25,760.35],[760.37,760.45],[760.49,760.75],[760.79,761.11],[761.15,761.33]]},{"id":156,"p":23,"en":"Which we cared about, of course.","zh":"这当然是我们关心的。","s":761.51,"e":762.83,"w":[[761.63,761.77],[761.81,761.87],[761.93,762.19],[762.21,762.41],[762.43,762.49],[762.53,762.83]]},{"id":157,"p":23,"en":"And so we think where you want to use this is evaluative situations, like social threat situations.","zh":"我们认为，你应该在被评价的场合用它，比如有社交威胁的场合。","s":762.83,"e":772.72,"w":[[767.37,767.43],[767.43,767.47],[767.47,767.51],[767.51,767.61],[767.61,767.77],[767.79,767.85],[767.87,768.0],[768.02,768.06],[768.22,768.44],[768.46,768.64],[768.78,768.86],[768.92,769.7],[769.76,770.36],[770.38,770.52],[770.64,771.04],[771.16,771.5],[771.82,772.48]]},{"id":158,"p":23,"en":"Where are you being evaluated, either by your friends?","zh":"你在哪里被评价？比如被朋友评价？","s":772.72,"e":774.86,"w":[[772.84,772.98],[772.98,773.04],[773.04,773.14],[773.16,773.34],[773.34,773.94],[774.0,774.16],[774.18,774.28],[774.3,774.42],[774.48,774.82]]},{"id":159,"p":23,"en":"For teenagers, it's at the lunchroom table.","zh":"对青少年来说，可能是在食堂的饭桌上。","s":774.86,"e":777.83,"w":[[774.98,775.1],[775.54,776.08],[776.14,776.24],[776.48,776.54],[776.56,776.62],[776.68,777.12],[777.18,777.58]]},{"id":160,"p":23,"en":"For some people it's speaking at a school board meeting.","zh":"对有些人来说，是在学校董事会上发言。","s":778.66,"e":781.56,"w":[[778.78,778.88],[778.92,779.08],[779.1,779.28],[779.3,779.4],[779.42,779.84],[780.28,780.36],[780.42,780.44],[780.78,781.04],[781.08,781.3],[781.34,781.62]]},{"id":161,"p":23,"en":"It might be giving a pitch or giving a talk like this or doing a job interview.","zh":"也可能是做一次项目推介、做一场像这样的演讲，或者参加一次求职面试。","s":781.56,"e":787.61,"w":[[781.68,781.74],[781.76,781.92],[781.94,782.0],[782.08,782.36],[782.42,782.44],[782.52,782.93],[783.45,783.63],[784.27,784.51],[784.53,784.55],[784.59,784.79],[784.83,785.01],[785.03,785.35],[785.63,785.81],[786.61,786.85],[786.87,786.89],[786.95,787.21],[787.27,787.61]]},{"id":162,"p":23,"en":"We decided that the one that most people could relate to because most people had been through, was the job interview.","zh":"我们最后选了求职面试，因为大多数人都经历过，最能感同身受。","s":787.61,"e":793.08,"w":[[788.57,788.61],[788.67,789.05],[789.11,789.21],[789.25,789.31],[789.41,789.53],[789.55,789.67],[789.85,790.05],[790.05,790.25],[790.25,790.37],[790.41,790.65],[790.69,790.75],[790.79,791.01],[791.03,791.21],[791.23,791.41],[791.45,791.55],[791.57,791.73],[791.77,791.97],[791.97,792.05],[792.09,792.17],[792.21,792.43],[792.47,792.83]]},{"id":163,"p":24,"en":"So we published these findings, and the media are all over it, and they say, Okay, so this is what you do when you go in for the job interview, right?","zh":"我们发表了这些发现，媒体一拥而上，说：“好，那你去求职面试时就这么做，对吧？”","s":793.35,"e":801.87,"w":[[793.47,793.57],[794.81,794.87],[794.93,795.29],[795.67,795.83],[795.87,796.39],[796.73,796.83],[796.87,796.95],[796.97,797.23],[797.27,797.35],[797.39,797.51],[797.55,797.71],[797.71,797.76],[797.76,797.82],[797.82,797.92],[798.02,798.2],[799.34,799.58],[799.66,799.72],[799.78,799.9],[799.92,799.98],[800.0,800.1],[800.12,800.2],[800.22,800.28],[800.32,800.4],[800.42,800.48],[800.48,800.52],[800.58,800.64],[800.66,800.74],[800.76,800.82],[800.84,801.02],[801.06,801.32],[801.36,801.62]]},{"id":164,"p":26,"en":"You know, so we were of course horrified, and said, Oh my God, no, that's not what we meant at all.","zh":"我们当然吓坏了，说：“天哪，不是的，我们完全不是这个意思。”","s":803.0,"e":807.56,"w":[[803.12,803.18],[803.18,803.28],[803.38,803.44],[803.54,803.6],[803.96,804.1],[804.1,804.16],[804.16,804.36],[804.38,804.94],[805.08,805.26],[805.54,805.68],[805.72,805.78],[805.78,805.88],[805.9,806.1],[806.14,806.18],[806.52,806.68],[806.7,806.8],[806.82,806.9],[806.92,806.98],[807.02,807.26],[807.32,807.4],[807.46,807.62]]},{"id":165,"p":26,"en":"For numerous reasons, no, don't do that.","zh":"出于种种原因，不，千万别这样做。","s":807.56,"e":810.52,"w":[[807.68,807.8],[808.46,808.82],[808.88,809.2],[809.48,809.54],[809.8,809.98],[810.06,810.1],[810.18,810.38]]},{"id":166,"p":26,"en":"Again, this is not about you talking to other people.","zh":"再说一遍，这不是关于你和别人说话。","s":810.52,"e":812.95,"w":[[810.64,810.86],[810.88,811.0],[811.02,811.1],[811.16,811.3],[811.34,811.56],[811.64,811.8],[812.22,812.52],[812.52,812.58],[812.65,812.79],[812.83,813.05]]},{"id":167,"p":26,"en":"It's you talking to yourself.","zh":"而是你和自己对话。","s":812.95,"e":814.39,"w":[[813.07,813.17],[813.23,813.33],[813.37,813.69],[813.69,813.73],[813.75,814.15]]},{"id":168,"p":26,"en":"What do you do before you go into a job interview?","zh":"去面试之前，你会做什么？","s":814.39,"e":816.41,"w":[[814.51,814.63],[814.65,814.71],[814.73,814.81],[814.83,814.89],[814.95,815.21],[815.23,815.31],[815.33,815.39],[815.47,815.57],[815.63,815.65],[815.67,815.87],[815.91,816.21]]},{"id":169,"p":26,"en":"You do this.","zh":"你会这样。","s":816.41,"e":817.4,"w":[[816.53,816.61],[816.65,816.73],[816.85,817.15]]},{"id":170,"p":26,"en":"You're sitting down.","zh":"你坐着。","s":817.81,"e":818.61,"w":[[817.93,818.07],[818.13,818.43],[818.47,818.69]]},{"id":171,"p":26,"en":"You're looking at your iPhone -- or your Android, not trying to leave anyone out.","zh":"你在看你的 iPhone——或者安卓手机，我可不想冷落任何人。","s":818.61,"e":822.28,"w":[[818.73,818.85],[818.87,819.11],[819.13,819.19],[819.21,819.31],[819.47,819.87],[820.27,820.33],[820.35,820.43],[820.51,820.95],[821.01,821.15],[821.17,821.35],[821.35,821.39],[821.41,821.55],[821.55,821.83],[821.87,822.03]]},{"id":172,"p":26,"en":"You're looking at your notes, you're hunching up, making yourself small, when really what you should be doing maybe is this, like, in the bathroom, right?","zh":"你在看笔记，弓着背，把自己缩得小小的，而其实你也许应该这样做，比如在洗手间里，对吧？","s":823.69,"e":830.47,"w":[[823.81,823.95],[823.99,824.21],[824.21,824.25],[824.27,824.39],[824.43,824.73],[824.77,824.89],[824.93,825.25],[825.27,825.35],[825.43,825.67],[825.67,825.97],[826.05,826.35],[826.39,826.49],[826.55,826.77],[826.81,826.91],[826.93,827.01],[827.03,827.19],[827.21,827.27],[827.33,827.56],[827.6,827.9],[828.06,828.16],[828.26,828.58],[828.64,828.84],[828.88,828.94],[828.96,829.04],[829.04,829.46],[829.96,830.22]]},{"id":173,"p":26,"en":"Do that.","zh":"这样做。","s":830.52,"e":830.94,"w":[[830.64,830.72],[830.78,830.98]]},{"id":174,"p":26,"en":"Find two minutes.","zh":"找出两分钟。","s":830.94,"e":831.92,"w":[[831.06,831.28],[831.3,831.44],[831.46,831.72]]},{"id":175,"p":26,"en":"So that's what we want to test.","zh":"这就是我们想测试的。","s":831.92,"e":832.94,"w":[[832.04,832.1],[832.14,832.3],[832.32,832.4],[832.42,832.46],[832.5,832.6],[832.62,832.66],[832.72,833.0]]},{"id":176,"p":26,"en":"Okay?","zh":"好吗？","s":832.94,"e":833.32,"w":[[833.06,833.3]]},{"id":177,"p":26,"en":"So we bring people into a lab, and they do either high- or low-power poses again, they go through a very stressful job interview.","zh":"我们把人请进实验室，他们同样先做高权力或低权力姿势，然后参加一场压力很大的求职面试。","s":833.32,"e":841.71,"w":[[833.44,833.52],[833.58,833.64],[833.72,833.9],[833.94,834.24],[834.66,834.88],[834.94,834.96],[835.02,835.36],[835.8,836.32],[836.8,836.92],[836.96,837.02],[837.2,837.38],[837.44,837.64],[837.64,837.7],[837.82,837.92],[837.96,838.18],[838.22,838.54],[838.58,838.92],[839.28,839.38],[839.42,839.46],[839.56,839.74],[839.74,839.76],[839.88,840.16],[840.24,840.7],[840.74,840.98],[841.06,841.46]]},{"id":178,"p":26,"en":"It's five minutes long.","zh":"面试五分钟。","s":841.74,"e":843.24,"w":[[841.86,841.96],[842.04,842.32],[842.36,842.63],[842.71,842.99]]},{"id":179,"p":26,"en":"They are being recorded.","zh":"整个过程都被录像。","s":843.35,"e":845.21,"w":[[843.47,843.63],[843.79,843.97],[844.45,844.69],[844.73,845.25]]},{"id":180,"p":26,"en":"They're being judged also, and the judges are trained to give no nonverbal feedback, so they look like this.","zh":"他们还会被评判，评委受过训练，不给任何非语言反馈，所以看起来是这样的。","s":845.21,"e":853.11,"w":[[845.33,845.49],[845.53,845.79],[845.89,846.31],[846.43,846.71],[847.37,847.53],[847.63,847.71],[847.81,848.39],[849.01,849.15],[849.21,849.61],[849.63,849.71],[849.75,849.93],[850.07,850.19],[850.41,850.87],[850.95,851.45],[851.87,851.95],[852.03,852.15],[852.25,852.41],[852.49,852.69],[852.75,852.99]]},{"id":181,"p":26,"en":"Imagine this is the person interviewing you.","zh":"想象一下这就是面试你的人。","s":853.11,"e":855.26,"w":[[853.23,853.65],[853.69,853.81],[853.85,853.91],[853.95,854.01],[854.03,854.31],[854.37,854.87],[854.91,855.01]]},{"id":182,"p":26,"en":"So for five minutes, nothing, and this is worse than being heckled.","zh":"整整五分钟毫无反应，这比被人起哄还难受。","s":855.83,"e":860.35,"w":[[855.95,856.03],[856.09,856.21],[856.29,856.59],[856.61,856.85],[857.09,857.6],[858.0,858.1],[858.12,858.28],[858.34,858.44],[858.56,858.9],[858.94,859.08],[859.18,859.46],[859.62,860.1]]},{"id":183,"p":26,"en":"People hate this.","zh":"人们非常讨厌这种感觉。","s":860.5,"e":861.93,"w":[[860.62,860.98],[861.16,861.44],[861.48,861.68]]},{"id":184,"p":26,"en":"It's what Marianne LaFrance calls \"standing in social quicksand.\"","zh":"这就是玛丽安·拉弗朗斯所说的“陷在社交流沙里”。","s":862.18,"e":865.57,"w":[[862.3,862.44],[862.46,862.62],[862.68,863.0],[863.0,863.4],[863.42,863.62],[863.7,864.14],[864.18,864.24],[864.34,864.66],[864.7,865.32]]},{"id":185,"p":26,"en":"So this really spikes your cortisol.","zh":"这会让你的皮质醇飙升。","s":865.58,"e":867.8,"w":[[865.7,865.78],[865.86,866.02],[866.2,866.54],[866.62,866.94],[866.98,867.08],[867.12,867.58]]},{"id":186,"p":26,"en":"So this is the job interview we put them through, because we really wanted to see what happened.","zh":"这就是我们让他们经历的面试，因为我们真的想看看会发生什么。","s":867.8,"e":871.61,"w":[[867.92,868.0],[868.06,868.18],[868.24,868.32],[868.34,868.44],[868.48,868.7],[868.74,869.0],[869.04,869.1],[869.16,869.3],[869.32,869.42],[869.46,869.64],[869.64,869.8],[869.8,869.86],[869.92,870.12],[870.16,870.36],[870.38,870.42],[870.52,870.68],[870.8,870.92],[870.98,871.36]]},{"id":187,"p":26,"en":"We then have these coders look at these tapes, four of them.","zh":"然后我们请了四位编码员观看这些录像。","s":872.27,"e":875.39,"w":[[872.39,872.45],[872.51,872.65],[872.71,872.85],[872.87,873.05],[873.09,873.61],[873.97,874.09],[874.13,874.19],[874.21,874.39],[874.41,874.69],[874.73,874.93],[874.97,875.03],[875.05,875.19]]},{"id":188,"p":26,"en":"They're blind to the hypothesis.","zh":"他们不知道我们的假设。","s":875.39,"e":876.95,"w":[[875.51,875.67],[875.69,875.95],[875.97,876.01],[876.05,876.11],[876.15,876.95]]},{"id":189,"p":26,"en":"They're blind to the conditions.","zh":"他们也不知道分组情况。","s":876.95,"e":878.19,"w":[[877.31,877.45],[877.47,877.69],[877.71,877.75],[877.79,877.85],[877.87,878.29]]},{"id":190,"p":26,"en":"They have no idea who's been posing in what pose, and they end up looking at these sets of tapes, and they say, \"We want to hire these people,\" all the high-power posers.","zh":"他们完全不知道谁摆了什么姿势，看完这些录像后，他们说：“我们想雇用这些人。”——全都是做了高权力姿势的人。","s":878.19,"e":889.78,"w":[[878.31,878.41],[878.41,878.51],[878.57,878.67],[878.91,879.17],[879.29,879.49],[879.53,879.65],[879.69,880.07],[880.11,880.19],[880.23,880.41],[880.47,880.93],[881.45,881.69],[883.01,883.13],[883.27,883.43],[883.51,883.63],[884.47,884.73],[884.77,884.83],[884.87,885.07],[885.53,885.75],[885.79,885.85],[885.89,886.17],[886.23,886.33],[886.33,886.43],[886.47,886.61],[886.85,886.91],[886.95,887.05],[887.07,887.11],[887.2,887.5],[887.56,887.78],[887.8,888.12],[888.44,888.54],[888.58,888.66],[888.7,888.9],[888.9,889.14],[889.22,889.56]]},{"id":191,"p":26,"en":"\"We don't want to hire these people.","zh":"“我们不想雇用这些人。","s":889.78,"e":891.1,"w":[[889.9,889.96],[890.0,890.14],[890.14,890.24],[890.26,890.3],[890.32,890.54],[890.56,890.78],[890.8,891.1]]},{"id":192,"p":26,"en":"We also evaluate these people much more positively overall.\"","zh":"我们对这些人的整体评价也高得多。”","s":891.1,"e":895.29,"w":[[891.82,891.88],[891.96,892.14],[892.5,893.02],[893.04,893.2],[893.22,893.44],[893.52,893.72],[893.82,893.98],[894.0,894.5],[894.6,895.04]]},{"id":193,"p":26,"en":"But what's driving it?","zh":"可是，原因是什么呢？","s":895.54,"e":896.97,"w":[[895.66,895.76],[895.8,896.0],[896.08,896.56],[896.6,896.72]]},{"id":194,"p":26,"en":"It's not about the content of the speech.","zh":"不在于讲话的内容。","s":897.14,"e":899.51,"w":[[897.26,897.4],[897.5,897.7],[897.74,897.98],[898.0,898.08],[898.12,898.64],[898.64,898.7],[898.74,898.8],[898.86,899.26]]},{"id":195,"p":26,"en":"It's about the presence that they're bringing to the speech.","zh":"而在于他们讲话时展现出的状态和气场。","s":899.58,"e":902.58,"w":[[899.7,899.82],[899.86,900.06],[900.08,900.14],[900.22,900.8],[901.14,901.26],[901.28,901.42],[901.48,901.8],[901.82,901.88],[901.92,901.98],[902.04,902.33]]},{"id":196,"p":26,"en":"Because we rate them on all these variables related to competence, like, how well-structured is the speech?","zh":"因为我们用各种与能力相关的指标给他们打分，比如讲话结构清不清晰？","s":902.65,"e":908.08,"w":[[902.77,902.97],[902.99,903.05],[903.15,903.35],[903.35,903.45],[903.49,903.55],[903.67,903.83],[903.87,904.05],[904.07,904.43],[904.49,904.79],[904.83,904.89],[905.21,905.81],[905.83,905.97],[906.31,906.41],[906.47,906.61],[906.67,907.17],[907.21,907.31],[907.35,907.43],[907.47,907.83]]},{"id":197,"p":26,"en":"How good is it?","zh":"讲得好不好？","s":908.13,"e":908.67,"w":[[908.25,908.35],[908.41,908.57],[908.61,908.67],[908.71,908.77]]},{"id":198,"p":26,"en":"What are their qualifications?","zh":"他们的资历如何？","s":908.67,"e":909.97,"w":[[908.79,908.89],[908.91,908.97],[908.97,909.07],[909.09,909.77]]},{"id":199,"p":26,"en":"No effect on those things.","zh":"这些方面都没有差别。","s":909.97,"e":911.71,"w":[[910.09,910.19],[910.31,910.67],[910.79,910.87],[910.93,911.17],[911.21,911.47]]},{"id":200,"p":26,"en":"This is what's affected.","zh":"受影响的是这些。","s":911.71,"e":913.14,"w":[[911.83,911.99],[912.05,912.13],[912.17,912.35],[912.39,912.89]]},{"id":201,"p":26,"en":"These kinds of things.","zh":"这类东西。","s":913.21,"e":914.6,"w":[[913.33,913.59],[913.63,913.91],[913.93,914.01],[914.07,914.35]]},{"id":202,"p":26,"en":"People are bringing their true selves, basically.","zh":"基本上，人们展现出了真实的自己。","s":914.65,"e":916.85,"w":[[914.77,915.07],[915.15,915.25],[915.29,915.57],[915.57,915.69],[915.73,915.95],[916.03,916.43],[916.49,916.91]]},{"id":203,"p":26,"en":"They're bringing themselves.","zh":"他们把自己带了进去。","s":916.85,"e":918.12,"w":[[916.97,917.12],[917.12,917.36],[917.36,917.96]]},{"id":204,"p":26,"en":"They bring their ideas, but as themselves, with no, you know, residue over them.","zh":"他们带来了自己的想法，但是以自己的身份，没有什么，你知道，包袱压着。","s":918.12,"e":922.97,"w":[[918.24,918.34],[918.36,918.52],[918.54,918.66],[918.78,919.12],[919.18,919.3],[919.44,919.6],[919.66,920.26],[920.54,920.66],[920.72,920.8],[921.38,921.44],[921.44,921.52],[921.7,922.18],[922.26,922.44],[922.48,922.72]]},{"id":205,"p":26,"en":"So this is what's driving the effect, or mediating the effect.","zh":"这就是产生效果、或者说起中介作用的因素。","s":923.14,"e":927.09,"w":[[923.26,923.34],[923.62,923.84],[924.02,924.1],[924.14,924.32],[924.36,924.72],[924.74,924.82],[924.84,925.16],[925.22,925.28],[925.94,926.36],[926.36,926.44],[926.48,926.84]]},{"id":206,"p":27,"en":"So when I tell people about this, that our bodies change our minds and our minds can change our behavior, and our behavior can change our outcomes, they say to me, \"It feels fake.\"","zh":"当我告诉别人这些——身体改变心灵、心灵能改变行为、行为能改变结果——他们会对我说：“这感觉很假。”","s":927.94,"e":938.77,"w":[[928.06,928.16],[929.44,929.54],[929.58,929.6],[929.68,930.02],[930.02,930.2],[930.24,930.5],[930.56,930.82],[931.46,931.58],[931.6,931.7],[931.74,932.07],[932.13,932.35],[932.37,932.45],[932.49,932.85],[932.85,932.93],[932.95,933.03],[933.07,933.33],[933.35,933.47],[933.51,933.75],[933.77,933.85],[933.87,934.35],[934.43,934.49],[934.51,934.59],[934.61,934.95],[934.97,935.07],[935.09,935.29],[935.29,935.35],[935.43,935.81],[935.83,935.93],[936.03,936.17],[936.21,936.27],[936.31,936.39],[937.85,937.91],[937.97,938.19],[938.37,938.69]]},{"id":207,"p":27,"en":"Right?","zh":"对吧？","s":938.77,"e":939.09,"w":[[938.89,939.11]]},{"id":208,"p":27,"en":"So I said, fake it till you make it.","zh":"所以我说，假装直到成功。","s":939.09,"e":940.92,"w":[[939.21,939.25],[939.39,939.41],[939.47,939.63],[939.71,939.93],[939.93,939.99],[940.01,940.13],[940.17,940.25],[940.27,940.51],[940.53,940.67]]},{"id":209,"p":27,"en":"It's not me.","zh":"“可那不是我。","s":941.63,"e":942.54,"w":[[941.75,941.87],[941.91,942.05],[942.19,942.29]]},{"id":210,"p":27,"en":"I don't want to get there and then still feel like a fraud.","zh":"我不想到了那一步，还觉得自己是个骗子。","s":942.83,"e":946.15,"w":[[942.95,942.97],[942.99,943.13],[943.21,943.41],[943.47,943.53],[943.63,943.81],[943.87,944.15],[944.67,944.77],[944.79,944.93],[945.03,945.23],[945.27,945.45],[945.47,945.59],[945.61,945.63],[945.71,946.15]]},{"id":211,"p":27,"en":"I don't want to feel like an impostor.","zh":"我不想觉得自己是个冒牌货。","s":946.15,"e":947.5,"w":[[946.27,946.31],[946.31,946.43],[946.43,946.51],[946.53,946.57],[946.57,946.69],[946.71,946.81],[946.84,946.88],[946.9,947.5]]},{"id":212,"p":27,"en":"I don't want to get there only to feel like I'm not supposed to be here.","zh":"我不想到了那里，却觉得自己不该在那儿。”","s":947.5,"e":951.53,"w":[[947.94,947.96],[947.96,948.08],[948.1,948.2],[948.22,948.26],[948.32,948.48],[948.52,948.68],[948.78,948.96],[949.02,949.06],[949.14,949.36],[949.44,949.72],[950.12,950.22],[950.26,950.4],[950.44,950.72],[950.74,950.8],[950.84,950.94],[951.06,951.28]]},{"id":213,"p":27,"en":"And that really resonated with me, because I want to tell you a little story about being an impostor and feeling like I'm not supposed to be here.","zh":"这让我很有共鸣，因为我想给你们讲个小故事，关于做“冒牌货”、觉得自己不该在那里的故事。","s":951.86,"e":959.07,"w":[[951.98,952.14],[952.7,952.86],[952.96,953.2],[953.28,953.76],[953.8,953.94],[954.0,954.06],[954.18,954.52],[954.92,954.94],[954.96,955.04],[955.06,955.1],[955.12,955.24],[955.24,955.3],[955.3,955.32],[955.34,955.5],[955.54,955.78],[955.82,956.02],[956.62,956.8],[956.82,956.88],[956.9,957.38],[957.4,957.46],[957.48,957.7],[957.7,957.84],[957.86,957.92],[957.96,958.06],[958.1,958.36],[958.38,958.42],[958.46,958.54],[958.62,958.82]]},{"id":214,"p":28,"en":"When I was 19, I was in a really bad car accident.","zh":"十九岁时，我遭遇了一场非常严重的车祸。","s":959.46,"e":962.77,"w":[[959.58,959.68],[959.76,959.78],[959.82,959.88],[959.88,960.18],[961.46,961.48],[961.5,961.62],[961.66,961.72],[961.74,961.77],[961.87,962.09],[962.15,962.31],[962.35,962.51],[962.57,962.83]]},{"id":215,"p":28,"en":"I was thrown out of a car, rolled several times.","zh":"我被甩出车外，翻滚了好几圈。","s":962.77,"e":966.07,"w":[[962.89,962.91],[962.91,963.01],[963.05,963.27],[963.29,963.39],[963.39,963.45],[963.45,963.47],[963.53,963.85],[965.05,965.39],[965.45,965.71],[965.75,966.11]]},{"id":216,"p":28,"en":"I was thrown from the car.","zh":"我被甩出了车子。","s":966.07,"e":967.46,"w":[[966.19,966.21],[966.23,966.35],[966.39,966.65],[966.69,966.81],[966.83,966.89],[966.93,967.21]]},{"id":217,"p":28,"en":"And I woke up in a head injury rehab ward, and I had been withdrawn from college, and I learned that my IQ had dropped by two standard deviations, which was very traumatic.","zh":"我在脑外伤康复病房醒来，已经被学校办了退学，我得知自己的智商下降了两个标准差，这对我打击非常大。","s":967.73,"e":981.65,"w":[[967.85,968.09],[968.45,968.47],[968.51,968.73],[968.73,968.81],[968.85,968.91],[968.93,968.95],[968.99,969.13],[969.17,969.43],[969.51,969.85],[969.89,970.15],[970.87,971.11],[971.27,971.29],[971.33,971.43],[971.45,971.55],[971.57,971.93],[971.97,972.09],[972.13,972.63],[974.03,974.29],[974.67,974.69],[975.23,975.53],[975.61,975.83],[975.95,976.11],[976.27,976.37],[976.59,976.72],[976.74,977.02],[977.06,977.16],[977.22,977.38],[977.44,977.78],[977.82,978.52],[979.24,979.4],[979.44,979.62],[980.6,980.8],[980.86,981.4]]},{"id":218,"p":28,"en":"I knew my IQ because I had identified with being smart, and I had been called gifted as a child.","zh":"我知道自己的智商，因为我一直认定自己很聪明，小时候还被称作天才儿童。","s":981.68,"e":986.29,"w":[[981.8,981.82],[981.84,981.96],[981.98,982.08],[982.18,982.28],[982.46,982.72],[982.8,982.82],[982.84,982.94],[983.02,983.54],[983.56,983.66],[983.7,983.9],[983.96,984.3],[984.3,984.38],[984.44,984.46],[984.48,984.56],[984.56,984.68],[984.72,984.98],[985.02,985.36],[985.38,985.46],[985.5,985.52],[985.6,986.04]]},{"id":219,"p":28,"en":"So I'm taken out of college, I keep trying to go back.","zh":"于是我离开了大学，我一直想回去。","s":986.42,"e":989.39,"w":[[986.54,986.62],[986.92,987.0],[987.18,987.42],[987.46,987.56],[987.56,987.6],[987.64,988.02],[988.1,988.12],[988.18,988.34],[988.38,988.62],[988.64,988.68],[988.72,988.78],[988.86,989.14]]},{"id":220,"p":28,"en":"They say, \"You're not going to finish college.","zh":"他们说：“你是读不完大学的。","s":989.44,"e":991.12,"w":[[989.56,989.66],[989.74,989.86],[989.88,990.0],[990.04,990.14],[990.14,990.28],[990.28,990.32],[990.36,990.6],[990.64,991.04]]},{"id":221,"p":28,"en":"Just, you know, there are other things for you to do, but that's not going to work out for you.\"","zh":"你知道，你还有别的事可以做，但这条路对你来说行不通。”","s":991.12,"e":995.68,"w":[[991.24,991.42],[991.77,991.83],[991.83,991.99],[992.73,993.01],[993.01,993.09],[993.15,993.31],[993.33,993.53],[993.55,993.63],[993.67,993.73],[993.77,993.83],[993.87,993.95],[994.05,994.15],[994.19,994.39],[994.45,994.55],[994.59,994.71],[994.71,994.75],[994.79,994.95],[995.01,995.13],[995.17,995.29],[995.35,995.43]]},{"id":222,"p":29,"en":"So I really struggled with this, and I have to say, having your identity taken from you, your core identity, and","zh":"我为此苦苦挣扎。我得说，当你的身份被夺走，你最核心的身份，","s":996.17,"e":1002.77,"w":[[996.29,996.37],[997.61,997.63],[998.11,998.35],[998.41,998.75],[998.77,998.89],[998.91,999.05],[999.09,999.17],[999.23,999.25],[999.35,999.47],[999.49,999.53],[999.61,999.75],[999.91,1000.21],[1000.21,1000.33],[1000.41,1000.81],[1000.91,1001.19],[1001.25,1001.39],[1001.45,1001.55],[1001.65,1001.77],[1001.79,1002.03],[1002.13,1002.45],[1002.53,1002.59]]},{"id":223,"p":29,"en":"for me it was being smart, having that taken from you, there's nothing that leaves you feeling more powerless than that.","zh":"对我来说就是“聪明”，当它被夺走时，没有什么比这更让你觉得无力了。","s":1002.77,"e":1008.55,"w":[[1002.89,1003.01],[1003.07,1003.13],[1003.21,1003.27],[1003.29,1003.39],[1003.45,1003.67],[1003.77,1004.15],[1004.77,1005.01],[1005.01,1005.11],[1005.15,1005.41],[1005.45,1005.59],[1005.65,1005.75],[1005.85,1006.01],[1006.09,1006.41],[1006.41,1006.54],[1006.62,1006.84],[1006.86,1006.94],[1006.98,1007.24],[1007.26,1007.38],[1007.4,1007.86],[1007.9,1008.02],[1008.06,1008.3]]},{"id":224,"p":29,"en":"So I felt entirely powerless.","zh":"所以我觉得自己完全无能为力。","s":1009.0,"e":1010.33,"w":[[1009.12,1009.16],[1009.26,1009.28],[1009.32,1009.46],[1009.48,1009.88],[1009.92,1010.3]]},{"id":225,"p":29,"en":"I worked and worked, and I got lucky, and worked, and got lucky, and worked.","zh":"我努力再努力，运气也不错，继续努力，又走了运，继续努力。","s":1010.33,"e":1013.94,"w":[[1011.06,1011.08],[1011.08,1011.32],[1011.38,1011.46],[1011.52,1011.74],[1011.8,1011.9],[1011.96,1011.98],[1012.0,1012.12],[1012.16,1012.42],[1012.54,1012.66],[1012.7,1012.94],[1012.96,1013.04],[1013.06,1013.18],[1013.22,1013.44],[1013.5,1013.58],[1013.64,1013.94]]},{"id":226,"p":30,"en":"Eventually I graduated from college.","zh":"最终我大学毕业了。","s":1013.94,"e":1016.29,"w":[[1014.46,1014.92],[1014.98,1015.0],[1015.04,1015.46],[1015.48,1015.58],[1015.64,1016.04]]},{"id":227,"p":30,"en":"It took me four years longer than my peers, and I convinced someone, my angel advisor, Susan Fiske,","zh":"我比同龄人多花了四年，后来我说服了一个人——我的贵人导师苏珊·菲斯克——","s":1016.7,"e":1023.67,"w":[[1016.82,1016.86],[1016.88,1017.02],[1017.06,1017.1],[1017.18,1017.34],[1017.38,1017.56],[1017.6,1017.82],[1017.86,1017.96],[1017.98,1018.08],[1018.14,1018.52],[1019.14,1019.28],[1019.48,1019.5],[1019.82,1020.24],[1020.3,1020.68],[1021.36,1021.49],[1021.65,1021.97],[1022.49,1023.01],[1023.13,1023.41],[1023.47,1023.75]]},{"id":228,"p":30,"en":"to take me on, and so I ended up at Princeton, and I was like, I am not supposed to be here.","zh":"收下我，于是我进了普林斯顿，而我心想：我不该在这里。","s":1023.67,"e":1028.84,"w":[[1023.79,1023.85],[1023.89,1024.11],[1024.15,1024.21],[1024.33,1024.49],[1024.95,1025.05],[1025.07,1025.11],[1025.21,1025.23],[1025.29,1025.49],[1025.51,1025.59],[1025.63,1025.69],[1025.73,1026.17],[1026.25,1026.35],[1026.45,1026.47],[1026.51,1026.61],[1026.65,1026.87],[1027.17,1027.19],[1027.39,1027.49],[1027.57,1027.73],[1027.79,1028.09],[1028.11,1028.17],[1028.21,1028.29],[1028.39,1028.59]]},{"id":229,"p":30,"en":"I am an impostor.","zh":"我是个冒牌货。","s":1029.11,"e":1030.22,"w":[[1029.23,1029.25],[1029.29,1029.35],[1029.37,1029.43],[1029.45,1029.97]]},{"id":230,"p":30,"en":"And the night before my first-year talk, and the first-year talk at Princeton is a 20-minute talk to 20 people.","zh":"在我一年级汇报的前一晚——普林斯顿的一年级汇报，就是面对 20 个人讲 20 分钟。","s":1030.43,"e":1035.79,"w":[[1030.55,1030.69],[1030.81,1030.89],[1030.93,1031.15],[1031.19,1031.45],[1031.47,1031.55],[1031.61,1031.85],[1031.87,1031.99],[1032.03,1032.25],[1032.27,1032.37],[1032.53,1032.59],[1032.61,1032.83],[1032.85,1032.97],[1032.99,1033.15],[1033.19,1033.25],[1033.27,1033.59],[1033.63,1033.69],[1033.73,1033.75],[1033.79,1034.05],[1034.11,1034.31],[1034.33,1034.61],[1034.91,1034.97],[1035.03,1035.29],[1035.35,1035.65]]},{"id":231,"p":30,"en":"That's it.","zh":"就这么点事。","s":1035.79,"e":1036.65,"w":[[1035.91,1036.13],[1036.23,1036.4]]},{"id":232,"p":30,"en":"I was so afraid of being found out the next day that I called her and said, \"I'm quitting.\"","zh":"我太害怕第二天被人识破了，于是给她打电话说：“我要退出。”","s":1037.06,"e":1042.13,"w":[[1037.18,1037.2],[1037.24,1037.36],[1037.48,1037.6],[1037.74,1038.14],[1038.16,1038.22],[1038.24,1038.44],[1038.5,1038.8],[1038.86,1038.98],[1039.02,1039.08],[1039.1,1039.36],[1039.4,1039.62],[1040.04,1040.16],[1040.26,1040.28],[1040.34,1040.62],[1040.64,1040.74],[1040.78,1040.86],[1040.9,1041.08],[1041.32,1041.42],[1041.5,1041.88]]},{"id":233,"p":30,"en":"She was like, \"You are not quitting, because I took a gamble on you, and you're staying.","zh":"她说：“你不能退出，因为我在你身上押了宝，你要留下来。","s":1042.62,"e":1046.87,"w":[[1042.74,1042.82],[1042.86,1042.96],[1042.98,1043.16],[1043.28,1043.38],[1043.44,1043.54],[1043.58,1043.74],[1043.8,1044.18],[1044.48,1044.7],[1044.78,1044.8],[1044.84,1044.96],[1045.0,1045.02],[1045.08,1045.46],[1045.52,1045.6],[1045.66,1045.78],[1045.86,1045.94],[1045.96,1046.1],[1046.14,1046.62]]},{"id":234,"p":30,"en":"You're going to stay, and this is what you're going to do.","zh":"你要留下来，接下来你要这样做。","s":1046.9,"e":1049.23,"w":[[1047.02,1047.14],[1047.14,1047.24],[1047.24,1047.28],[1047.36,1047.74],[1048.18,1048.26],[1048.28,1048.38],[1048.4,1048.46],[1048.48,1048.58],[1048.58,1048.7],[1048.7,1048.82],[1048.82,1048.86],[1048.9,1048.98]]},{"id":235,"p":30,"en":"You are going to fake it.","zh":"你要假装。","s":1050.7,"e":1051.43,"w":[[1050.82,1050.88],[1050.88,1050.94],[1050.94,1051.06],[1051.06,1051.1],[1051.14,1051.43],[1051.45,1051.49]]},{"id":236,"p":30,"en":"You're going to do every talk that you ever get asked to do.","zh":"只要有人请你做报告，你就去做。","s":1051.43,"e":1054.04,"w":[[1051.55,1051.67],[1051.67,1051.77],[1051.77,1051.81],[1051.83,1051.89],[1052.03,1052.23],[1052.31,1052.61],[1052.65,1052.77],[1052.79,1052.89],[1052.95,1053.11],[1053.15,1053.25],[1053.33,1053.57],[1053.59,1053.65],[1053.71,1053.79]]},{"id":237,"p":30,"en":"You're just going to do it and do it and do it, even if you're terrified and just paralyzed and having an out-of-body experience,","zh":"你就一次又一次地去做，哪怕你吓坏了、浑身僵住、感觉灵魂出窍，","s":1054.13,"e":1060.97,"w":[[1054.25,1054.37],[1054.37,1054.49],[1054.51,1054.65],[1054.65,1054.69],[1054.79,1054.87],[1054.99,1055.07],[1055.17,1055.27],[1055.31,1055.41],[1055.49,1055.57],[1055.63,1055.73],[1055.79,1055.89],[1055.99,1056.11],[1056.25,1056.43],[1056.45,1056.51],[1056.55,1056.67],[1056.71,1057.49],[1057.87,1057.95],[1057.97,1058.11],[1058.17,1058.95],[1059.27,1059.39],[1059.55,1059.79],[1059.83,1059.89],[1059.97,1060.11],[1060.13,1060.17],[1060.19,1060.39],[1060.45,1061.05]]},{"id":238,"p":30,"en":"until you have this moment where you say, 'Oh my gosh, I'm doing it.","zh":"直到某一刻你会说：‘天哪，我做到了。","s":1060.97,"e":1064.37,"w":[[1061.09,1061.33],[1061.35,1061.41],[1061.47,1061.65],[1061.67,1061.81],[1061.87,1062.13],[1062.17,1062.29],[1062.31,1062.41],[1062.49,1062.73],[1063.39,1063.45],[1063.47,1063.59],[1063.63,1063.89],[1063.97,1064.03],[1064.09,1064.37],[1064.39,1064.47]]},{"id":239,"p":30,"en":"Like, I have become this.","zh":"我已经变成这样的人了。","s":1064.37,"e":1066.26,"w":[[1064.49,1064.67],[1064.95,1064.97],[1065.07,1065.23],[1065.27,1065.67],[1065.73,1066.01]]},{"id":240,"p":30,"en":"I am actually doing this.'\" So that's what I did.","zh":"我真的在做这件事。’”于是我就这么做了。","s":1066.4,"e":1068.42,"w":[[1066.52,1066.54],[1066.56,1066.64],[1066.72,1067.0],[1067.04,1067.28],[1067.28,1067.42],[1067.76,1067.82],[1067.86,1068.02],[1068.02,1068.12],[1068.2,1068.22],[1068.26,1068.4]]},{"id":241,"p":30,"en":"Five years in grad school, a few years, you know, I'm at Northwestern, I moved to Harvard, I'm at Harvard,","zh":"读了五年研究生，之后几年，你知道，我在西北大学，后来去了哈佛，我在哈佛，","s":1068.42,"e":1073.8,"w":[[1068.54,1068.84],[1068.84,1069.02],[1069.06,1069.1],[1069.14,1069.4],[1069.46,1069.7],[1070.18,1070.2],[1070.2,1070.34],[1070.42,1070.72],[1070.76,1070.84],[1070.84,1070.94],[1070.98,1071.04],[1071.06,1071.12],[1071.16,1071.8],[1071.9,1071.92],[1072.0,1072.18],[1072.18,1072.22],[1072.32,1072.74],[1073.38,1073.44],[1073.46,1073.54],[1073.58,1073.86]]},{"id":242,"p":30,"en":"I'm not really thinking about it anymore, but for a long time I had been thinking, \"Not supposed to be here.\"","zh":"我已经不怎么想这件事了，但很长一段时间里，我一直在想：“我不该在这里。”","s":1073.8,"e":1078.83,"w":[[1073.92,1073.98],[1074.02,1074.12],[1074.16,1074.34],[1074.5,1074.82],[1074.86,1075.1],[1075.14,1075.22],[1075.28,1075.76],[1076.18,1076.28],[1076.32,1076.42],[1076.46,1076.48],[1076.52,1076.72],[1076.76,1076.96],[1077.02,1077.04],[1077.06,1077.14],[1077.16,1077.26],[1077.28,1077.58],[1077.86,1078.0],[1078.04,1078.26],[1078.26,1078.32],[1078.34,1078.4],[1078.46,1078.58]]},{"id":243,"p":31,"en":"So at the end of my first year at Harvard, a student who had not talked in class the entire semester,","zh":"在我在哈佛第一年的期末，有个学生整个学期都没在课上发过言，","s":1079.94,"e":1087.03,"w":[[1080.06,1080.1],[1080.1,1080.14],[1080.36,1080.44],[1080.5,1080.62],[1080.66,1080.72],[1080.74,1080.86],[1080.92,1081.19],[1081.21,1081.33],[1081.35,1081.39],[1081.45,1081.79],[1084.45,1084.47],[1084.57,1084.87],[1084.93,1084.99],[1085.03,1085.11],[1085.17,1085.35],[1085.41,1085.67],[1085.69,1085.75],[1085.81,1086.11],[1086.21,1086.29],[1086.31,1086.67],[1086.71,1087.11]]},{"id":244,"p":31,"en":"who I had said, \"Look, you've gotta participate or else you're going to fail,\" came into my office.","zh":"我曾对她说：“听着，你得参与课堂，不然会不及格。”她来到了我的办公室。","s":1087.03,"e":1091.39,"w":[[1087.15,1087.23],[1087.29,1087.31],[1087.33,1087.41],[1087.49,1087.67],[1087.99,1088.13],[1088.19,1088.33],[1088.33,1088.59],[1088.61,1089.25],[1089.27,1089.33],[1089.37,1089.51],[1089.51,1089.63],[1089.63,1089.73],[1089.73,1089.77],[1089.81,1090.15],[1090.71,1090.89],[1090.91,1091.05],[1091.07,1091.17],[1091.23,1091.43]]},{"id":245,"p":31,"en":"I really didn't know her at all.","zh":"我其实完全不了解她。","s":1091.39,"e":1092.68,"w":[[1091.51,1091.53],[1091.53,1091.71],[1091.73,1091.85],[1091.87,1091.99],[1092.05,1092.15],[1092.17,1092.23],[1092.29,1092.43]]},{"id":246,"p":31,"en":"She came in totally defeated, and she said, \"I'm not supposed to be here.\"","zh":"她进来时整个人都很挫败，说：“我不该在这里。”","s":1094.65,"e":1099.45,"w":[[1094.77,1094.85],[1094.89,1095.15],[1095.21,1095.37],[1095.51,1095.89],[1095.96,1096.36],[1096.4,1096.5],[1096.54,1096.6],[1096.72,1096.96],[1098.08,1098.14],[1098.18,1098.32],[1098.36,1098.64],[1098.66,1098.72],[1098.76,1098.82],[1098.96,1099.2]]},{"id":247,"p":31,"en":"And that was the moment for me.","zh":"那一刻对我意义重大。","s":1104.3,"e":1105.48,"w":[[1104.42,1104.52],[1104.54,1104.68],[1104.72,1104.82],[1104.86,1104.94],[1104.98,1105.28],[1105.32,1105.42],[1105.46,1105.52]]},{"id":248,"p":31,"en":"Because two things happened.","zh":"因为发生了两件事。","s":1105.48,"e":1106.94,"w":[[1105.6,1105.92],[1106.14,1106.32],[1106.36,1106.58],[1106.62,1106.92]]},{"id":249,"p":31,"en":"One was that I realized, oh my gosh, I don't feel like that anymore.","zh":"第一件是我意识到：天哪，我已经没有那种感觉了。","s":1106.94,"e":1110.94,"w":[[1107.06,1107.2],[1107.22,1107.34],[1107.36,1107.48],[1107.56,1107.58],[1107.66,1108.14],[1108.84,1108.88],[1108.94,1109.04],[1109.08,1109.3],[1109.36,1109.38],[1109.42,1109.54],[1109.58,1109.72],[1109.74,1109.86],[1109.88,1109.96],[1109.96,1110.78]]},{"id":250,"p":31,"en":"I don't feel that anymore, but she does, and I get that feeling.","zh":"我不再那样觉得了，但她还那样觉得，而我懂那种感觉。","s":1110.94,"e":1114.27,"w":[[1111.67,1111.69],[1111.71,1111.85],[1111.91,1112.07],[1112.07,1112.19],[1112.21,1112.51],[1112.55,1112.67],[1112.77,1112.89],[1112.99,1113.23],[1113.27,1113.35],[1113.45,1113.47],[1113.55,1113.71],[1113.75,1113.89],[1113.97,1114.33]]},{"id":251,"p":31,"en":"And the second was, she is supposed to be here!","zh":"第二件是：她就该在这里！","s":1114.27,"e":1116.86,"w":[[1114.39,1114.47],[1114.49,1114.55],[1114.63,1114.93],[1114.97,1115.13],[1115.25,1115.35],[1115.53,1115.65],[1115.71,1116.05],[1116.07,1116.13],[1116.17,1116.23],[1116.35,1116.61]]},{"id":252,"p":31,"en":"Like, she can fake it, she can become it.","zh":"她可以假装，她可以成为那样的人。","s":1116.89,"e":1119.13,"w":[[1117.01,1117.17],[1117.23,1117.33],[1117.41,1117.55],[1117.65,1117.93],[1117.95,1118.05],[1118.15,1118.23],[1118.29,1118.41],[1118.45,1118.81],[1118.83,1118.93]]},{"id":253,"p":32,"en":"So I was like, \"Yes, you are!","zh":"于是我说：“对，你该在这里！","s":1119.13,"e":1121.15,"w":[[1119.25,1119.29],[1119.29,1119.31],[1119.31,1119.43],[1119.45,1119.61],[1120.21,1120.41],[1120.49,1120.59],[1120.75,1120.93]]},{"id":254,"p":32,"en":"You are supposed to be here!","zh":"你就该在这里！","s":1121.15,"e":1122.59,"w":[[1121.27,1121.37],[1121.45,1121.57],[1121.61,1121.87],[1121.87,1121.93],[1121.97,1122.03],[1122.15,1122.37]]},{"id":255,"p":32,"en":"And tomorrow you're going to fake it, you're going to make yourself powerful, and, you know --","zh":"明天你要假装，让自己变得有力量，然后——","s":1122.59,"e":1127.09,"w":[[1122.71,1122.79],[1122.83,1123.19],[1123.23,1123.37],[1123.37,1123.49],[1123.49,1123.53],[1123.63,1123.91],[1123.93,1124.05],[1124.05,1124.35],[1124.39,1124.51],[1124.51,1124.55],[1124.55,1124.69],[1124.69,1124.93],[1124.97,1125.45],[1126.04,1126.2],[1126.62,1126.68],[1126.7,1126.84]]},{"id":256,"p":34,"en":"And you're going to go into the classroom, and you are going to give the best comment ever.\"","zh":"你要走进教室，发表一个史上最棒的观点。”","s":1127.68,"e":1138.83,"w":[[1127.8,1132.76],[1134.18,1135.04],[1135.04,1135.18],[1135.18,1135.24],[1135.24,1135.3],[1135.4,1135.54],[1135.56,1135.64],[1135.68,1136.3],[1136.7,1136.78],[1136.86,1136.96],[1137.02,1137.1],[1137.1,1137.24],[1137.24,1137.28],[1137.32,1137.44],[1137.46,1137.52],[1137.62,1137.86],[1137.9,1138.26],[1138.34,1138.58]]},{"id":257,"p":34,"en":"You know?","zh":"你懂吗？","s":1139.0,"e":1139.59,"w":[[1139.12,1139.18],[1139.18,1139.34]]},{"id":258,"p":34,"en":"And she gave the best comment ever, and people turned around and were like, oh my God, I didn't even notice her sitting there.","zh":"结果她真的发表了最棒的观点，大家都转过头来，心想：天哪，我都没注意到她坐在那儿。","s":1139.64,"e":1145.68,"w":[[1139.76,1139.86],[1140.04,1140.12],[1140.38,1140.75],[1140.89,1140.97],[1141.03,1141.33],[1141.39,1141.75],[1141.79,1141.97],[1142.03,1142.11],[1142.15,1142.39],[1142.45,1142.61],[1142.61,1142.75],[1142.75,1142.81],[1142.81,1142.89],[1142.89,1143.05],[1143.15,1143.23],[1143.27,1143.41],[1143.49,1143.75],[1143.83,1143.85],[1143.87,1144.01],[1144.01,1144.19],[1144.21,1144.57],[1144.61,1144.77],[1144.91,1145.19],[1145.23,1145.43]]},{"id":259,"p":35,"en":"She comes back to me months later, and I realized that she had not just faked it till she made it, she had actually faked it till she became it.","zh":"几个月后她又来找我，我意识到，她不只是“假装直到成功”，她是真的“假装直到成为”了那样的人。","s":1145.71,"e":1154.27,"w":[[1146.75,1146.83],[1146.89,1147.09],[1147.11,1147.25],[1147.27,1147.31],[1147.35,1147.41],[1147.47,1147.67],[1147.77,1148.03],[1148.25,1148.39],[1148.61,1148.63],[1148.77,1149.29],[1149.29,1149.37],[1149.43,1149.51],[1149.57,1149.65],[1149.73,1149.91],[1149.97,1150.19],[1150.41,1150.69],[1150.71,1150.77],[1150.81,1150.95],[1151.01,1151.09],[1151.21,1151.43],[1151.47,1151.57],[1151.99,1152.07],[1152.09,1152.19],[1152.25,1152.53],[1152.65,1152.93],[1152.95,1153.03],[1153.29,1153.43],[1153.47,1153.57],[1153.63,1154.07],[1154.11,1154.27]]},{"id":260,"p":35,"en":"So she had changed.","zh":"所以她改变了。","s":1154.27,"e":1155.97,"w":[[1154.73,1154.79],[1154.87,1154.95],[1155.01,1155.11],[1155.19,1155.72]]},{"id":261,"p":35,"en":"And so I want to say to you, don't fake it till you make it.","zh":"所以我想对你们说：不要只是假装直到成功。","s":1156.44,"e":1160.29,"w":[[1156.56,1156.68],[1156.76,1156.84],[1158.06,1158.08],[1158.1,1158.2],[1158.22,1158.26],[1158.34,1158.48],[1158.52,1158.58],[1158.62,1158.7],[1158.8,1159.02],[1159.1,1159.32],[1159.34,1159.4],[1159.42,1159.56],[1159.56,1159.64],[1159.68,1159.92],[1159.94,1160.04]]},{"id":262,"p":35,"en":"Fake it till you become it.","zh":"要假装直到成为。","s":1160.38,"e":1161.73,"w":[[1160.5,1160.7],[1160.72,1160.76],[1160.8,1160.92],[1160.92,1161.0],[1161.02,1161.36],[1161.38,1161.48]]},{"id":263,"p":35,"en":"Do it enough until you actually become it and internalize.","zh":"坚持做下去，直到你真正变成那样的人，并把它内化。","s":1163.16,"e":1166.31,"w":[[1163.28,1163.36],[1163.46,1163.52],[1163.6,1163.96],[1164.06,1164.28],[1164.3,1164.38],[1164.46,1164.74],[1164.78,1165.12],[1165.14,1165.22],[1165.26,1165.34],[1165.38,1166.06]]},{"id":264,"p":36,"en":"The last thing I'm going to leave you with is this.","zh":"最后我想留给你们的是这句话。","s":1166.46,"e":1168.59,"w":[[1166.58,1166.64],[1166.68,1166.88],[1166.9,1167.04],[1167.1,1167.16],[1167.16,1167.26],[1167.26,1167.3],[1167.34,1167.58],[1167.6,1167.68],[1167.72,1167.9],[1167.92,1168.02],[1168.08,1168.34]]},{"id":265,"p":36,"en":"Tiny tweaks can lead to big changes.","zh":"微小的调整能带来巨大的改变。","s":1169.12,"e":1173.06,"w":[[1169.24,1169.54],[1169.62,1169.98],[1171.11,1171.25],[1171.33,1171.59],[1171.95,1172.05],[1172.11,1172.25],[1172.31,1172.81]]},{"id":266,"p":36,"en":"So, this is two minutes.","zh":"就两分钟。","s":1173.73,"e":1176.14,"w":[[1173.85,1173.93],[1174.85,1175.01],[1175.07,1175.15],[1175.29,1175.47],[1175.53,1175.89]]},{"id":267,"p":36,"en":"Two minutes, two minutes, two minutes.","zh":"两分钟，两分钟，两分钟。","s":1176.15,"e":1178.15,"w":[[1176.27,1176.47],[1176.53,1176.83],[1176.93,1177.07],[1177.11,1177.35],[1177.39,1177.55],[1177.57,1177.91]]},{"id":268,"p":36,"en":"Before you go into the next stressful evaluative situation, for two minutes, try doing this, in the elevator, in a bathroom stall, at your desk behind closed doors.","zh":"下次你要进入一个让你紧张、被人评价的场合之前，花两分钟试着这样做：在电梯里、在洗手间隔间里、在关上门的办公桌前。","s":1178.15,"e":1186.9,"w":[[1178.27,1178.59],[1178.59,1178.71],[1178.71,1178.77],[1178.87,1178.99],[1179.01,1179.09],[1179.13,1179.35],[1179.37,1179.73],[1179.73,1180.19],[1180.21,1180.81],[1181.31,1181.43],[1181.49,1181.69],[1181.75,1182.07],[1182.15,1182.41],[1182.45,1182.71],[1182.73,1182.91],[1182.97,1183.03],[1183.05,1183.11],[1183.25,1183.75],[1184.07,1184.15],[1184.17,1184.19],[1184.25,1184.67],[1184.73,1185.01],[1185.42,1185.5],[1185.54,1185.64],[1185.68,1185.94],[1185.98,1186.28],[1186.3,1186.6],[1186.64,1186.94]]},{"id":269,"p":36,"en":"That's what you want to do.","zh":"这就是你要做的。","s":1186.9,"e":1188.05,"w":[[1187.02,1187.22],[1187.24,1187.36],[1187.38,1187.46],[1187.46,1187.6],[1187.62,1187.66],[1187.7,1187.8]]},{"id":270,"p":36,"en":"Configure your brain to cope the best in that situation.","zh":"让你的大脑调整到最能应对那个场合的状态。","s":1188.22,"e":1191.52,"w":[[1188.34,1188.82],[1188.84,1188.96],[1189.0,1189.32],[1189.74,1189.82],[1189.9,1190.2],[1190.24,1190.34],[1190.44,1190.76],[1190.82,1190.88],[1190.9,1191.04],[1191.08,1191.56]]},{"id":271,"p":36,"en":"Get your testosterone up.","zh":"让你的睾酮升上去。","s":1191.52,"e":1192.98,"w":[[1191.64,1191.8],[1191.82,1191.92],[1191.94,1192.6],[1192.64,1192.74]]},{"id":272,"p":36,"en":"Get your cortisol down.","zh":"让你的皮质醇降下来。","s":1192.98,"e":1194.33,"w":[[1193.1,1193.22],[1193.26,1193.36],[1193.38,1193.82],[1193.84,1194.08]]},{"id":273,"p":36,"en":"Don't leave that situation feeling like, oh, I didn't show them who I am.","zh":"别带着“唉，我没让他们看到真实的我”这种感觉离开。","s":1194.38,"e":1198.15,"w":[[1194.5,1194.72],[1194.82,1195.06],[1195.08,1195.24],[1195.28,1195.76],[1195.82,1196.08],[1196.08,1196.24],[1196.4,1196.58],[1196.66,1196.68],[1196.72,1196.86],[1196.92,1197.04],[1197.08,1197.18],[1197.2,1197.3],[1197.42,1197.44],[1197.6,1197.9]]},{"id":274,"p":36,"en":"Leave that situation feeling like, I really feel like I got to say who I am and show who I am.","zh":"要带着“我真的说出了我是谁、展现了我是谁”的感觉离开。","s":1198.32,"e":1202.69,"w":[[1198.44,1198.66],[1198.68,1198.8],[1198.86,1199.26],[1199.3,1199.48],[1199.48,1199.62],[1199.82,1199.84],[1200.0,1200.18],[1200.22,1200.41],[1200.43,1200.57],[1200.63,1200.65],[1200.69,1200.81],[1200.85,1200.93],[1201.03,1201.25],[1201.33,1201.41],[1201.55,1201.57],[1201.65,1201.79],[1201.83,1201.93],[1201.97,1202.11],[1202.15,1202.23],[1202.37,1202.39],[1202.45,1202.63]]},{"id":275,"p":37,"en":"So I want to ask you first, you know, both to try power posing, and also I want to ask you to share the science, because this is simple.","zh":"所以我想请你们，一是试试权力姿势，二是把这门科学分享出去，因为它很简单。","s":1202.69,"e":1213.64,"w":[[1202.81,1203.21],[1203.31,1203.33],[1203.35,1203.45],[1203.47,1203.51],[1203.61,1203.79],[1203.83,1203.91],[1203.97,1204.27],[1204.75,1204.81],[1204.81,1204.95],[1205.77,1206.03],[1206.21,1206.35],[1206.97,1207.29],[1207.37,1207.65],[1207.73,1208.17],[1209.09,1209.19],[1209.25,1209.55],[1210.17,1210.19],[1210.21,1210.31],[1210.33,1210.37],[1210.47,1210.69],[1210.75,1210.87],[1211.29,1211.37],[1211.47,1211.69],[1211.73,1211.79],[1211.93,1212.41],[1212.41,1212.59],[1212.59,1212.75],[1212.81,1212.89],[1213.03,1213.39]]},{"id":276,"p":37,"en":"I don't have ego involved in this.","zh":"我在这件事上没有私心。","s":1213.87,"e":1215.75,"w":[[1213.99,1214.01],[1214.03,1214.21],[1214.29,1214.45],[1214.53,1214.71],[1214.79,1215.15],[1215.17,1215.24],[1215.28,1215.5]]},{"id":277,"p":37,"en":"Give it away.","zh":"把它送出去。","s":1215.98,"e":1216.98,"w":[[1216.1,1216.26],[1216.28,1216.34],[1216.38,1216.74]]},{"id":278,"p":37,"en":"Share it with people, because the people who can use it the most are the ones with no resources and no technology and no status and no power.","zh":"分享给别人，因为最用得上它的，正是那些没有资源、没有技术、没有地位、没有权力的人。","s":1216.98,"e":1225.78,"w":[[1217.1,1217.34],[1217.38,1217.44],[1217.48,1217.6],[1217.62,1217.92],[1217.96,1218.2],[1218.2,1218.28],[1218.32,1218.56],[1218.6,1218.66],[1218.7,1218.82],[1218.92,1219.06],[1219.06,1219.14],[1219.16,1219.24],[1219.28,1219.54],[1219.56,1219.62],[1219.62,1219.68],[1219.76,1219.9],[1219.92,1220.04],[1220.1,1220.18],[1220.32,1220.9],[1221.32,1221.5],[1222.0,1222.1],[1222.68,1223.38],[1223.86,1224.04],[1224.34,1224.42],[1224.6,1225.02],[1225.08,1225.18],[1225.24,1225.3],[1225.44,1225.78]]},{"id":279,"p":37,"en":"Give it to them because they can do it in private.","zh":"把它送给他们，因为他们可以私下里做。","s":1225.78,"e":1228.1,"w":[[1225.9,1226.06],[1226.08,1226.14],[1226.2,1226.28],[1226.36,1226.64],[1226.78,1227.02],[1227.02,1227.14],[1227.16,1227.28],[1227.32,1227.4],[1227.46,1227.52],[1227.58,1227.66],[1227.72,1228.2]]},{"id":280,"p":37,"en":"They need their bodies, privacy and two minutes, and it can significantly change the outcomes of their life.","zh":"他们只需要自己的身体、一点私人空间和两分钟，而这能大大改变他们人生的结果。","s":1228.1,"e":1234.05,"w":[[1228.22,1228.32],[1228.36,1228.48],[1228.5,1228.6],[1228.66,1229.08],[1229.42,1229.88],[1229.96,1230.1],[1230.15,1230.33],[1230.37,1230.71],[1231.25,1231.35],[1231.37,1231.43],[1231.47,1231.61],[1231.69,1232.35],[1232.41,1232.71],[1232.73,1232.81],[1232.89,1233.25],[1233.27,1233.33],[1233.35,1233.45],[1233.51,1233.81]]},{"id":281,"p":38,"en":"Thank you.","zh":"谢谢大家。","s":1234.05,"e":1234.72,"w":[[1234.17,1234.37],[1234.39,1234.47]]}]};